files.data:
:root {
  --bg: #000000;
  --title: #fcfcfc;
  --white: #ffffff;
  --text-footnote: 0.9375rem; /* 15 — iOS Subhead */
  --text-body: 1.0625rem; /* 17 — iOS Body */
  --text-title: 1.25rem; /* 20 — iOS Title 3 */
  --text-title-tablet: 1.5rem; /* 24 */
  --weight-regular: 400;
  --weight-medium: 500;
  --weight-semibold: 600;
  --leading: 1.3;
  --duration-snappy: 220ms;
  --ease-snappy: cubic-bezier(0.175, 0.885, 0.32, 1.1);
  --duration-smooth: 300ms;
  --ease-smooth: cubic-bezier(0.19, 1, 0.22, 1);
  --duration-swift: 800ms;
  --ease-swift: cubic-bezier(0.175, 0.885, 0.32, 1.275);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  min-height: 100%;
  background: var(--bg);
  color: var(--white);
}

html {
  font-size: 16px;
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
}

body {
  min-height: 100dvh;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "SF Pro Text", sans-serif;
  font-size: var(--text-body);
  font-weight: var(--weight-regular);
  font-optical-sizing: auto;
  line-height: var(--leading);
  letter-spacing: normal;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

img {
  display: block;
  max-width: 100%;
  height: auto;
  user-select: none;
  -webkit-user-drag: none;
}

.page {
  position: relative;
  display: flex;
  flex-direction: column;
  min-height: 100dvh;
  min-height: 100svh;
  background: var(--bg);
  overflow-x: hidden;
  padding:
    calc(20px + env(safe-area-inset-top))
    32px
    calc(24px + env(safe-area-inset-bottom));
}

.powered {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 20px;
  margin: 0 auto;
  flex: 0 0 auto;
}

.powered-by,
.powered-grok {
  font-size: var(--text-footnote);
  font-weight: var(--weight-medium);
  letter-spacing: -0.01em;
  line-height: 1.2;
  white-space: nowrap;
}

.powered-by {
  color: rgba(255, 255, 255, 0.3);
}

.powered-brand {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  height: 20px;
}

.grok-logo {
  display: block;
  width: 14px;
  height: 14px;
  flex: 0 0 14px;
}

.powered-grok {
  color: rgba(255, 255, 255, 0.6);
}

.content {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 100%;
  max-width: 338px;
  margin: 0 auto;
  gap: 40px;
  padding-top: 28px;
}

/* The desktop fallback is opt-in: hidden unless the device is a desktop. */
.content-desktop {
  display: none;
}

.ob {
  width: 100%;
  max-width: 338px;
  height: 294px;
  overflow: hidden;
  flex: 0 0 auto;
}

.ob-img {
  width: 100%;
  height: 294px;
  object-fit: cover;
  object-position: top center;
}

.ob-ipad {
  display: none;
}

.copy {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
  width: 100%;
}

h1 {
  margin: 0;
  width: 100%;
  align-self: stretch;
  padding: 0;
  color: var(--title);
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "SF Pro Display", sans-serif;
  font-size: var(--text-title);
  font-weight: var(--weight-semibold);
  font-optical-sizing: auto;
  line-height: var(--leading);
  letter-spacing: -0.02em;
  text-align: center;
  text-wrap: balance;
  mix-blend-mode: plus-lighter;
}

.steps {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
}

.step {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  margin: 0;
  min-height: 1.5em;
  white-space: nowrap;
}

.muted {
  display: inline-flex;
  align-items: center;
  color: var(--white);
  opacity: 0.5;
  font-size: 1em;
  font-weight: var(--weight-regular);
  letter-spacing: normal;
  line-height: var(--leading);
}

.add-label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.plus-icon {
  display: block;
  width: 16px;
  height: 16px;
  flex: 0 0 16px;
}

.add-text {
  display: inline-flex;
  align-items: center;
  color: var(--white);
  font-size: 1em;
  font-weight: var(--weight-medium);
  letter-spacing: normal;
  line-height: var(--leading);
}

.glass {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  flex: 0 0 24px;
  border-radius: 999px;
  overflow: hidden;
  background: transparent;
}

.glass--icon {
  background: transparent;
  box-shadow:
    inset 0 2px 1px -1px rgba(255, 255, 255, 0.25),
    inset 0 -2px 1px -1px rgba(255, 255, 255, 0.25);
  overflow: hidden;
}

.glass--icon img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
}

.loc-ipad {
  display: none;
}

.step-ios27,
.step-ios-legacy {
  display: none;
}

html.device-phone.ios-27-plus .step-ios27,
html.device-phone.ios-below-27 .step-ios-legacy,
html.device-phone:not(.ios-27-plus):not(.ios-below-27) .step-ios-legacy,
html.device-tablet .step-ios-legacy {
  display: flex;
}

/* Desktop (also the no-JS default): swap the tutorial for a visible fallback
   that links back to the app instead of hiding everything. */
html.device-desktop .content {
  display: none;
}

html.device-desktop .content-desktop {
  display: flex;
  max-width: 420px;
}

.desktop-note {
  margin: 0;
  color: rgba(255, 255, 255, 0.5);
  text-align: center;
  text-wrap: balance;
}

.desktop-open {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 10px 20px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.1);
  box-shadow:
    inset 0 2px 1px -1px rgba(255, 255, 255, 0.25),
    inset 0 -2px 1px -1px rgba(255, 255, 255, 0.25);
  color: var(--white);
  font-weight: var(--weight-medium);
  text-decoration: none;
}

.desktop-open:hover {
  background: rgba(255, 255, 255, 0.16);
}

html.device-tablet .page {
  display: flex;
  align-items: center;
  justify-content: center;
  padding:
    calc(24px + env(safe-area-inset-top))
    24px
    calc(24px + env(safe-area-inset-bottom));
}

html.device-tablet .powered {
  display: none;
}

html.device-tablet .content {
  max-width: 634px;
  margin: 0;
  gap: 40px;
}

html.device-tablet .ob {
  max-width: 634px;
}

html.device-tablet .ob-phone {
  display: none;
}

html.device-tablet .ob-ipad {
  display: block;
}

html.device-tablet h1 {
  font-size: var(--text-title-tablet);
  letter-spacing: -0.015em;
}

html.device-tablet .step {
  gap: 10px;
}

html.device-tablet .glass {
  width: 30px;
  height: 30px;
  flex-basis: 30px;
}

html.device-tablet .plus-icon {
  width: 18px;
  height: 18px;
  flex-basis: 18px;
}

html.device-tablet .loc-phone {
  display: none;
}

html.device-tablet .loc-ipad {
  display: inline;
}

@media (max-height: 700px) {
  html.device-phone .content {
    justify-content: center;
  }
}

/**
 * Dev-only `/__app-env` endpoint: the client env the running Vite server
 * resolved, as JSON.
 *
 * `scripts/check-auth-invariant.mjs` reads it to compare the live dev server's
 * `VITE_AUTH_ENABLED` against the value the next build will resolve. The
 * config is loaded even when Vite is started outside `scripts/with-app-env.mjs`
 * — the case that check exists to catch. These are the same values Vite inlines
 * into the client bundle, and `apply: "serve"` keeps the route out of deployed
 * apps.
 */
export const APP_ENV_ROUTE = "/__app-env";

export function appEnvPlugin() {
  return {
    name: "app-builder:app-env",
    apply: "serve",
    configureServer(server) {
      server.middlewares.use((req, res, next) => {
        const pathOnly = (req.url ?? "").split("?", 1)[0];
        if (pathOnly !== APP_ENV_ROUTE || (req.method ?? "GET").toUpperCase() !== "GET") {
          next();
          return;
        }
        const body = Buffer.from(JSON.stringify(server.config.env), "utf8");
        res.statusCode = 200;
        res.setHeader("content-type", "application/json; charset=utf-8");
        res.setHeader("cache-control", "no-cache");
        res.setHeader("content-length", String(body.byteLength));
        res.end(body);
      });
    },
  };
}

#!/usr/bin/env node
/**
 * Brand-asset gate shared by browser-smoke.mjs (and unit-testable without a
 * browser): a canvas app is almost always a game / visually rich app, and
 * those must ship a custom share card — the default og.grok.me placeholder is
 * not acceptable for them (see .grok/skills/og/SKILL.md).
 *
 * Games must also set type=x:game in src/lib/og/site.json so the platform
 * injector emits og:type for X game-card unfurls, and public/x-banner.jpg for
 * the 50:11 X feed card. A card file is enough for bake to emit /og.jpg, but
 * brand-check still requires site.json `"card": "custom"` so the agent-facing
 * contract stays explicit.
 *
 * Checked on the filesystem (not the served head) so preview and mid-scaffold
 * workspaces are judged the same way.
 *
 * Also runnable, so the background brand task can check its own work before it
 * reports (the parent answers without waiting for it):
 *
 *   node scripts/brand-check.mjs [--game] [--placeholder-ok] [--root <dir>]
 *
 * That run judges the files on disk even though the task is holding the
 * og-pending marker; the marker only silences what the parent's gates see. It
 * also requires the custom card: its caller is normally the pass that exists to
 * produce one, so the placeholder the parent tolerates for a plain utility is a
 * failed pass here. --placeholder-ok is for the other launch — a pass doing
 * favicon, PWA icons and title for a plain utility that keeps the og.grok.me
 * card — where no card is the expected verdict rather than a failure.
 */
import { existsSync, statSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { OG_SITE_REL_PATH, readOgSite, siteHasCustomCard } from "./grok-pwa-shared.mjs";

// Over this, link scrapers (X card previews included) time out or skip the
// image, so the card silently fails to unfurl. The og skill's JPEG contract
// (ffmpeg -q:v 4, ~150-300 KB) exists precisely to stay under it.
export const MAX_CARD_BYTES = 600 * 1024;

// Written by the brand task while it generates, removed when it finishes.
export const OG_PENDING_REL_PATH = ".grok/og-pending";
// A Stop mid-generation leaves the marker behind, so the demotion expires
// instead of hiding a missing card forever on that workspace.
export const OG_PENDING_MAX_AGE_MS = 10 * 60 * 1000;

export function siteDeclaresOgTypeGame(site) {
  return String(site?.type ?? "").toLowerCase() === "x:game";
}

export function ogPendingActive(workspaceRoot, now = Date.now()) {
  try {
    const { mtimeMs } = statSync(join(workspaceRoot, OG_PENDING_REL_PATH));
    return now - mtimeMs < OG_PENDING_MAX_AGE_MS;
  } catch {
    return false;
  }
}

/**
 * What the parent's gates see. The brand pass may still be generating when a
 * gate runs, and "missing" would send the agent to redo the task's work.
 *
 * In flight is silence, not a note: callers report this array as warnings, so
 * anything left in it — however it is worded — reaches the agent as one.
 */
export function computeBrandWarnings({
  hasCanvas,
  workspaceRoot = "/workspace",
  now = Date.now(),
}) {
  if (ogPendingActive(workspaceRoot, now)) return [];
  return brandWarningsOnDisk({ hasCanvas, workspaceRoot });
}

/**
 * The files on disk, marker ignored — the brand pass's own view of its work.
 * Deliberately not exported: a gate that reached for this instead of
 * `computeBrandWarnings` would warn about a card that is still generating.
 * `cardRequired` is for a caller that is itself the brand pass: for it the
 * placeholder is a failure, not the plain-utility default the parent's gate
 * leaves alone.
 */
function brandWarningsOnDisk({
  hasCanvas,
  workspaceRoot = "/workspace",
  cardRequired = false,
}) {
  const skillPath = join(workspaceRoot, ".grok/skills/og/SKILL.md");
  const sitePath = join(workspaceRoot, OG_SITE_REL_PATH);
  const site = readOgSite(workspaceRoot);
  const cardPath = [
    join(workspaceRoot, "public/og.jpg"),
    join(workspaceRoot, "public/og.png"),
  ].find(existsSync);
  const warnings = [];

  if (cardPath !== undefined) {
    if (statSync(cardPath).size > MAX_CARD_BYTES) {
      warnings.push(
        `BRAND WARNING: ${cardPath} is over 600 KB — link scrapers (X card previews included) `
          + "time out or skip images this heavy, so the card silently fails to unfurl. "
          + `Re-encode as JPEG (public/og.jpg, ffmpeg -q:v 4) per ${skillPath}.`,
      );
    }
    if (!siteHasCustomCard(site)) {
      warnings.push(
        `BRAND WARNING: ${cardPath} exists but ${sitePath} is missing "card": "custom". `
          + "Bake infers custom from the file, but set the flag in "
          + `${sitePath} per ${skillPath} so identity is explicit.`,
      );
    }
  } else if (hasCanvas) {
    warnings.push(
      `BRAND WARNING: this looks like a game/canvas app but ${workspaceRoot}/public/og.jpg `
        + "is missing. Games and visually rich apps must ship a custom 1200x630 share card "
        + "built from the app's own art — the default og.grok.me placeholder card is not "
        + `acceptable for them. You are not done: open ${skillPath} and finish the `
        + "brand-asset pass.",
    );
  } else if (cardRequired) {
    warnings.push(
      `BRAND WARNING: ${workspaceRoot}/public/og.jpg is missing and this pass exists to `
        + "produce it. Generate the 1200x630 card from the app's own art and hand it over "
        + `per ${skillPath}. If no image-generation tool is available in this session, `
        + "report that instead of reporting a pass — the app keeps the og.grok.me "
        + "placeholder.",
    );
  } else {
    warnings.push(
      "BRAND NOTE: no custom public/og.jpg — the platform will serve the og.grok.me placeholder. "
        + "Custom cards are the default for games of every kind (DOM board/word games included), "
        + "whimsical apps, creative tools, and brand-forward pages — only plain utilities "
        + "(converters, CRUD trackers, admin dashboards) keep the placeholder. If this app "
        + `is not a plain utility, finish the brand-asset pass per ${skillPath}.`,
    );
  }

  if (hasCanvas && !siteDeclaresOgTypeGame(site)) {
    warnings.push(
      'BRAND WARNING: this looks like a game/canvas app but src/lib/og/site.json is missing '
        + '"type": "x:game". X uses og:type=x:game to present the unfurl as a game card — set '
        + `it in ${sitePath} per ${skillPath}. Do not invent `
        + "x:type or overload twitter:card as the game signal.",
    );
  }

  // Games with a custom link card must also ship the 50:11 X feed card.
  // Skip while still on the og.grok.me placeholder — that pass has not started yet.
  if (hasCanvas && cardPath !== undefined) {
    const bannerPath = join(workspaceRoot, "public/x-banner.jpg");
    if (!existsSync(bannerPath)) {
      warnings.push(
        `BRAND WARNING: this looks like a game/canvas app but ${bannerPath} is missing. `
          + "Games need a 50:11 X feed card (1200×264 JPEG) at public/x-banner.jpg — "
          + `open ${skillPath} and finish the brand-asset pass.`,
      );
    } else if (statSync(bannerPath).size > MAX_CARD_BYTES) {
      warnings.push(
        `BRAND WARNING: ${bannerPath} is over 600 KB — link scrapers (X card previews `
          + "included) time out or skip images this heavy, so the feed card silently fails "
          + `to unfurl. Re-encode as JPEG (ffmpeg -q:v 4) per ${skillPath}.`,
      );
    }
  }

  return warnings;
}

export function parseBrandCheckArgs(argv) {
  const usage =
    "usage: node scripts/brand-check.mjs [--game] [--placeholder-ok] [--root <dir>]";
  let game = false;
  let placeholderOk = false;
  let root = null;
  for (let i = 0; i < argv.length; i += 1) {
    // --game runs the checks browser-smoke.mjs derives from a real <canvas>;
    // DOM board/word games need them too and have no canvas to detect.
    if (argv[i] === "--game") {
      game = true;
    } else if (argv[i] === "--placeholder-ok") {
      placeholderOk = true;
    } else if (argv[i] === "--root") {
      root = argv[++i];
      if (root === undefined) return { error: `--root needs a directory — ${usage}` };
    } else {
      return { error: `unexpected argument: ${argv[i]} — ${usage}` };
    }
  }
  return { game, placeholderOk, root };
}

function isBrandWarning(message) {
  return message.startsWith("BRAND WARNING:");
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const args = parseBrandCheckArgs(process.argv.slice(2));
  if (args.error) {
    console.error(JSON.stringify({ ok: false, error: args.error }, null, 2));
    process.exit(1);
  }
  const workspaceRoot = args.root ?? join(dirname(fileURLToPath(import.meta.url)), "..");
  // The caller here is the brand task checking its own work: it is holding the
  // marker (report it, but judge the assets on disk) and it owes a custom card
  // whether or not the app draws to a canvas — unless it was launched for a
  // plain utility that keeps the placeholder, which only it knows.
  const messages = brandWarningsOnDisk({
    hasCanvas: args.game,
    workspaceRoot,
    cardRequired: !args.placeholderOk,
  });
  const warnings = messages.filter(isBrandWarning);
  console.log(
    JSON.stringify(
      {
        ok: warnings.length === 0,
        workspaceRoot,
        pending: ogPendingActive(workspaceRoot),
        warnings: warnings.length,
        messages,
      },
      null,
      2,
    ),
  );
  process.exitCode = warnings.length === 0 ? 0 : 1;
}

import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { mkdtempSync, mkdirSync, readFileSync, utimesSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { test } from "node:test";
import {
  MAX_CARD_BYTES,
  OG_PENDING_MAX_AGE_MS,
  OG_PENDING_REL_PATH,
  computeBrandWarnings,
  ogPendingActive,
  parseBrandCheckArgs,
  siteDeclaresOgTypeGame,
} from "./brand-check.mjs";

const TEMPLATE_ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const SCRIPT = join(TEMPLATE_ROOT, "scripts/brand-check.mjs");

const GAME_SITE = JSON.stringify({ title: "Wild Race", type: "x:game", card: "custom" });
const UTILITY_SITE = JSON.stringify({ title: "Invoice" });
const UTILITY_CUSTOM_SITE = JSON.stringify({ title: "Invoice", card: "custom" });

function makeWorkspace({
  siteJson,
  cardFile,
  narrowFile,
  cardBytes = 200 * 1024,
  narrowBytes = 200 * 1024,
  pendingAgeMs,
} = {}) {
  const root = mkdtempSync(join(tmpdir(), "brand-check-"));
  mkdirSync(join(root, "public"), { recursive: true });
  mkdirSync(join(root, "src/lib/og"), { recursive: true });
  mkdirSync(join(root, ".grok"), { recursive: true });
  if (pendingAgeMs !== undefined) {
    const marker = join(root, OG_PENDING_REL_PATH);
    writeFileSync(marker, "");
    const when = new Date(Date.now() - pendingAgeMs);
    utimesSync(marker, when, when);
  }
  if (siteJson !== undefined) {
    writeFileSync(join(root, "src/lib/og/site.json"), siteJson);
  }
  if (cardFile !== undefined) {
    writeFileSync(join(root, "public", cardFile), Buffer.alloc(cardBytes, 7));
  }
  if (narrowFile !== undefined) {
    writeFileSync(join(root, "public", narrowFile), Buffer.alloc(narrowBytes, 7));
  }
  return root;
}

test("non-canvas app with no custom card gets a soft BRAND NOTE (utility exception)", () => {
  const root = makeWorkspace({ siteJson: UTILITY_SITE });
  const warnings = computeBrandWarnings({ hasCanvas: false, workspaceRoot: root });
  assert.equal(warnings.length, 1);
  assert.match(warnings[0], /^BRAND NOTE:/);
  assert.match(warnings[0], /plain utilit/);
  assert.doesNotMatch(warnings[0], /^BRAND WARNING:/);
});

test("non-canvas app with a compliant card is silent", () => {
  const root = makeWorkspace({ siteJson: UTILITY_CUSTOM_SITE, cardFile: "og.jpg" });
  assert.deepEqual(computeBrandWarnings({ hasCanvas: false, workspaceRoot: root }), []);
});

test("card file without site.json card=custom warns", () => {
  const root = makeWorkspace({ siteJson: UTILITY_SITE, cardFile: "og.jpg" });
  const warnings = computeBrandWarnings({ hasCanvas: false, workspaceRoot: root });
  assert.equal(warnings.length, 1);
  assert.match(warnings[0], /"card": "custom"/);
});

test("card file with missing site.json warns for card=custom", () => {
  const root = makeWorkspace({ cardFile: "og.jpg" });
  const warnings = computeBrandWarnings({ hasCanvas: false, workspaceRoot: root });
  assert.equal(warnings.length, 1);
  assert.match(warnings[0], /"card": "custom"/);
});

test("card file with invalid site.json warns for card=custom", () => {
  const root = makeWorkspace({ siteJson: "{not-json", cardFile: "og.jpg" });
  const warnings = computeBrandWarnings({ hasCanvas: false, workspaceRoot: root });
  assert.equal(warnings.length, 1);
  assert.match(warnings[0], /"card": "custom"/);
});

test("oversized card warns for non-canvas apps too", () => {
  const root = makeWorkspace({
    siteJson: UTILITY_CUSTOM_SITE,
    cardFile: "og.jpg",
    cardBytes: MAX_CARD_BYTES + 1,
  });
  const warnings = computeBrandWarnings({ hasCanvas: false, workspaceRoot: root });
  assert.equal(warnings.length, 1);
  assert.match(warnings[0], /over 600 KB/);
});

test("canvas app with no card warns 'missing' and missing og:type", () => {
  const root = makeWorkspace({ siteJson: UTILITY_SITE });
  const warnings = computeBrandWarnings({ hasCanvas: true, workspaceRoot: root });
  assert.equal(warnings.length, 2);
  assert.match(warnings[0], /og\.jpg.*is missing/s);
  assert.match(warnings[0], /not done/);
  assert.match(warnings[1], /site\.json/);
  assert.match(warnings[1], /og:type|x:game/);
});

test("canvas card without type still warns for og:type", () => {
  const root = makeWorkspace({ siteJson: UTILITY_CUSTOM_SITE, cardFile: "og.jpg" });
  const warnings = computeBrandWarnings({ hasCanvas: true, workspaceRoot: root });
  assert.match(warnings.join("\n"), /x:game/);
  assert.match(warnings.join("\n"), /x-banner\.jpg/);
});

test("oversized card warns on the scraper budget (jpg and legacy png)", () => {
  for (const cardFile of ["og.jpg", "og.png"]) {
