function fakeProcesses({ pids, ignoresTerm = [] }) {
  const alive = new Set(pids);
  const signals = [];
  return {
    signals,
    isAlive: (pid) => alive.has(pid),
    kill: (pid, signal) => {
      signals.push([pid, signal]);
      if (signal === "SIGKILL" || !ignoresTerm.includes(pid)) alive.delete(pid);
    },
    sleep: async () => {},
  };
}

test("terminatePids SIGTERMs live pids and skips dead ones", async () => {
  const fake = fakeProcesses({ pids: [11, 12] });
  const result = await terminatePids([11, 12, 13], fake);
  assert.deepEqual(result, { signalled: [11, 12], killed: [], stubborn: [] });
  assert.deepEqual(fake.signals, [
    [11, "SIGTERM"],
    [12, "SIGTERM"],
  ]);
});

test("terminatePids escalates to SIGKILL when SIGTERM is ignored", async () => {
  const fake = fakeProcesses({ pids: [11, 12], ignoresTerm: [12] });
  const result = await terminatePids([11, 12], fake);
  assert.deepEqual(result, { signalled: [11, 12], killed: [12], stubborn: [] });
  assert.deepEqual(fake.signals, [
    [11, "SIGTERM"],
    [12, "SIGTERM"],
    [12, "SIGKILL"],
  ]);
});

test("terminatePids reports a pid that survives SIGKILL as stubborn", async () => {
  const signals = [];
  const result = await terminatePids([11], {
    isAlive: () => true,
    kill: (pid, signal) => signals.push([pid, signal]),
    sleep: async () => {},
  });
  assert.deepEqual(result, { signalled: [11], killed: [11], stubborn: [11] });
  assert.deepEqual(signals, [
    [11, "SIGTERM"],
    [11, "SIGKILL"],
  ]);
});

test("terminatePids on a free port signals nothing", async () => {
  const fake = fakeProcesses({ pids: [] });
  const result = await terminatePids([], fake);
  assert.deepEqual(result, { signalled: [], killed: [], stubborn: [] });
  assert.deepEqual(fake.signals, []);
});

/**
 * Interactive Pairband product demo recorder.
 * Records real clicks/typing on desktop, then a separate mobile pass.
 * Output webms are muxed with narration via scripts/mux-demo.sh
 */
import { chromium } from "playwright";
import fs from "fs";
import path from "path";

const BASE = process.env.DEMO_BASE || "http://127.0.0.1:8080";
const OUT_DIR = "/workspace/screenshots/demo-assets";
const DESK_DIR = path.join(OUT_DIR, "video-desktop");
const MOB_DIR = path.join(OUT_DIR, "video-mobile");

for (const d of [DESK_DIR, MOB_DIR]) {
  fs.rmSync(d, { recursive: true, force: true });
  fs.mkdirSync(d, { recursive: true });
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function clickFirst(page, role, name, wait = 800) {
  const loc = page.getByRole(role, { name }).first();
  if ((await loc.count()) > 0) {
    await loc.click({ timeout: 5000 }).catch(() => {});
    await sleep(wait);
    return true;
  }
  return false;
}

async function fillFirst(page, selector, value) {
  // Prefer an enabled field — on-chain mode disables the optional first-buy input.
  const all = page.locator(selector);
  const n = await all.count();
  for (let i = 0; i < n; i++) {
    const loc = all.nth(i);
    if (await loc.isDisabled().catch(() => true)) continue;
    if (!(await loc.isVisible().catch(() => false))) continue;
    try {
      await loc.click({ timeout: 3000 });
      await loc.fill("");
      await loc.type(value, { delay: 18 });
      await sleep(400);
      return true;
    } catch {
      continue;
    }
  }
  return false;
}

async function recordDesktop() {
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext({
    viewport: { width: 1280, height: 800 },
    deviceScaleFactor: 1,
    recordVideo: { dir: DESK_DIR, size: { width: 1280, height: 800 } },
  });
  const page = await context.newPage();

  // 1) Landing (~18s)
  await page.goto(`${BASE}/`, { waitUntil: "networkidle", timeout: 60000 });
  await sleep(2500);
  await page.mouse.wheel(0, 420);
  await sleep(2000);
  await page.mouse.wheel(0, 500);
  await sleep(2000);
  await page.mouse.wheel(0, -900);
  await sleep(1500);

  // Open app
  if (!(await clickFirst(page, "link", /open app|launch app|enter app/i, 2000))) {
    await page.goto(`${BASE}/app`, { waitUntil: "networkidle" });
    await sleep(2000);
  }

  // 2) Discover (~22s)
  await sleep(1500);
  await fillFirst(page, 'input[placeholder*="Search"], input[type="search"]', "teal");
  await sleep(1200);
  // clear search / show filters
  const search = page.locator('input[placeholder*="Search"], input[type="search"]').first();
  if (await search.count()) {
    await search.fill("");
    await sleep(600);
  }
  for (const label of [/new/i, /market/i, /volume/i, /near/i]) {
    await clickFirst(page, "button", label, 700);
  }
  await clickFirst(page, "button", /new/i, 800);
  await page.mouse.wheel(0, 360);
  await sleep(1500);

  // 3) Token + buy (~28s)
  const card = page.locator('a[href*="/app/t/"]').first();
  if (await card.count()) {
    await card.click();
    await sleep(2500);
    await page.mouse.wheel(0, 200);
    await sleep(1000);
    await fillFirst(page, 'input[inputmode="decimal"], input[type="number"], input[type="text"]', "10");
    await sleep(800);
    await clickFirst(page, "button", /^\$?10$|buy|confirm|place order/i, 2200);
    // try explicit Buy button
    await clickFirst(page, "button", /buy /i, 2000);
    await page.mouse.wheel(0, 280);
    await sleep(1500);
  }

  // Look for a near-graduation / graduated token if Teal Machine exists
  await page.goto(`${BASE}/app`, { waitUntil: "networkidle" });
  await sleep(1200);
  const teal = page.getByText(/teal machine|TEAL/i).first();
  if (await teal.count()) {
    await teal.click();
    await sleep(2200);
    await page.mouse.wheel(0, 240);
    await sleep(1500);
  }

  // 4) Trade desk (~20s)
  await page.goto(`${BASE}/app/trade`, { waitUntil: "networkidle" });
  await sleep(2000);
  const pair = page.locator("button").filter({ hasText: /PAPER|TEAL|INK|BAND/i }).first();
  if (await pair.count()) {
    await pair.click();
    await sleep(1200);
  }
  await fillFirst(page, 'input[inputmode="decimal"], input[type="number"], input[type="text"]', "25");
  await sleep(800);
  await clickFirst(page, "button", /buy|sell|confirm/i, 1800);
  await page.mouse.wheel(0, 300);
  await sleep(1500);

  // 5) Tape (~12s)
  await page.goto(`${BASE}/app/activity`, { waitUntil: "networkidle" });
  await sleep(2500);
  await page.mouse.wheel(0, 260);
  await sleep(1500);

  // 6) Wallet (~14s)
  await page.goto(`${BASE}/app/me`, { waitUntil: "networkidle" });
  await sleep(2000);
  await clickFirst(page, "button", /faucet|claim|mint/i, 1800);
  await page.mouse.wheel(0, 320);
  await sleep(1500);

  // 7) AI create + launch (~30s)
  await page.goto(`${BASE}/app/create`, { waitUntil: "networkidle" });
  await sleep(1800);
  await fillFirst(
    page,
    "textarea",
    "A community token for indie game developers who ship weekly builds and share revenue on Arc.",
  );
  await sleep(800);
  await clickFirst(page, "button", /generate|ai|draft|suggest/i, 3500);
  await page.mouse.wheel(0, 220);
  await sleep(1200);
  // Prefer local preview launch so the demo never blocks on a wallet.
  const onChain = page.getByRole("checkbox", { name: /broadcast|arc testnet|on-chain/i }).first();
  if ((await onChain.count()) > 0 && (await onChain.isChecked().catch(() => false))) {
    await onChain.click().catch(() => {});
    await sleep(400);
  }
  // optional first buy field (enabled only in preview mode)
  await fillFirst(page, 'input[inputmode="decimal"], input[name*="buy"], input[type="number"]', "5");
  await sleep(600);
  await clickFirst(page, "button", /launch|create token|deploy/i, 2800);
  await sleep(2000);

  // Return to discover to show new listing
  await page.goto(`${BASE}/app`, { waitUntil: "networkidle" });
  await sleep(2500);

  await context.close();
  await browser.close();
}

async function recordMobile() {
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext({
    viewport: { width: 390, height: 844 },
    deviceScaleFactor: 2,
    isMobile: true,
    hasTouch: true,
    recordVideo: { dir: MOB_DIR, size: { width: 390, height: 844 } },
  });
  const page = await context.newPage();

  await page.goto(`${BASE}/`, { waitUntil: "networkidle" });
  await sleep(2000);
  if (!(await clickFirst(page, "link", /open app|trade|launch/i, 1800))) {
    await page.goto(`${BASE}/app`, { waitUntil: "networkidle" });
    await sleep(1500);
  }

  // Bottom nav tour
  for (const name of [/discover/i, /launch/i, /trade/i, /tape/i, /wallet/i]) {
    await clickFirst(page, "link", name, 1600);
  }
  await clickFirst(page, "link", /discover/i, 1200);
  await page.mouse.wheel(0, 280);
  await sleep(1000);

  const card = page.locator('a[href*="/app/t/"]').first();
  if (await card.count()) {
    await card.click();
    await sleep(2000);
    await fillFirst(page, 'input[inputmode="decimal"], input[type="text"]', "10");
    await clickFirst(page, "button", /buy/i, 1800);
  }

  await clickFirst(page, "link", /trade/i, 1800);
  await sleep(1200);
  await clickFirst(page, "link", /launch/i, 1800);
  await sleep(1500);

  await context.close();
  await browser.close();
}

function pickWebm(dir) {
  const vids = fs.readdirSync(dir).filter((f) => f.endsWith(".webm"));
  if (!vids.length) throw new Error(`No webm in ${dir}`);
  // largest = longest usually
  vids.sort((a, b) => fs.statSync(path.join(dir, b)).size - fs.statSync(path.join(dir, a)).size);
  return path.join(dir, vids[0]);
}

async function main() {
  console.log("Recording desktop…");
  await recordDesktop();
  console.log("Recording mobile…");
  await recordMobile();
  const desk = pickWebm(DESK_DIR);
  const mob = pickWebm(MOB_DIR);
  fs.writeFileSync(
    path.join(OUT_DIR, "record-paths.json"),
    JSON.stringify({ desktop: desk, mobile: mob }, null, 2),
  );
  console.log(JSON.stringify({ desktop: desk, mobile: mob }));
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

// @ts-check
/**
 * The sign-out sequence used by `src/lib/auth/client.ts`, kept here as a pure
 * module so its effects can be unit-tested (`node --test` only covers
 * `scripts/`), the same split `migration-plan.mjs` uses for the two appliers.
 *
 * The two environments authenticate differently, so they need different
 * answers to "the server did not reply":
 *
 * - **Live preview** — a partitioned iframe with no readable session cookie;
 *   the session rides the bearer token in `sessionStorage`. Dropping that token
 *   IS being signed out, so the server call is best effort and a wedged request
 *   must never strand the button. This is where the hang actually happens.
 * - **Deployed** — the session rides an HttpOnly `__Host-` cookie that JS
 *   cannot delete. ONLY a completed sign-out response clears it, and
 *   `server.ts` enables `session.cookieCache` (maxAge 300), so `/get-session`
 *   would keep answering from the cached cookie for minutes afterwards.
 *   Redirecting on a timeout would show the visitor "signed out" while their
 *   session is still live — so here we fail loudly instead of pretending.
 */

/**
 * Live preview: aggressive, because the local clear is what signs the user out.
 * The same-origin POST normally answers in tens of ms; lower would start
 * abandoning slow-but-working sign-outs for no gain.
 */
export const PREVIEW_SIGN_OUT_TIMEOUT_MS = 1500;

/**
 * Deployed: generous, because only the server can end this session — but still
 * bounded, so a wedged request reports failure the visitor can retry instead of
 * spinning forever. A sign-out still unanswered at 10s is not going to land.
 */
export const DEPLOYED_SIGN_OUT_TIMEOUT_MS = 10_000;

/**
 * How long to wait for a sign-out in this environment. Every sign-out network
 * call picks its bound here, so the preview/deployed split cannot drift apart
 * between callers.
 * @param {boolean} livePreview
 * @returns {number}
 */
export function signOutTimeoutMs(livePreview) {
  return livePreview ? PREVIEW_SIGN_OUT_TIMEOUT_MS : DEPLOYED_SIGN_OUT_TIMEOUT_MS;
}

/**
 * Run `start()` but give up after `timeoutMs`, reporting which happened. Never
 * rejects — callers decide what a failure means, and a `try/catch` around an
 * `await` does nothing for a promise that never settles.
 * @param {() => unknown} start
 * @param {number} timeoutMs
 * @returns {Promise<"ok" | "failed" | "timeout">}
 */
export function settleWithin(start, timeoutMs) {
  return new Promise((resolve) => {
    const timer = setTimeout(() => resolve("timeout"), timeoutMs);
    /** @param {"ok" | "failed"} outcome */
    const done = (outcome) => {
      clearTimeout(timer);
      resolve(outcome);
    };
    try {
      Promise.resolve(start()).then(
        () => done("ok"),
        () => done("failed"),
      );
    } catch {
      done("failed");
    }
  });
}

/**
 * @typedef {object} SignOutSteps
 * @property {boolean} livePreview Whether the app is the sandbox preview iframe.
 * @property {boolean} hasBearer Whether a preview bearer token is stored.
 * @property {() => unknown} requestSignOut Ask the server to end the session; must reject on a failed response.
 * @property {() => void} clearToken Drop the stored bearer token.
 * @property {() => void} redirect Leave the page.
 * @property {number} [timeoutMs]
 */

/**
 * End the session, then clear the local token and redirect.
 *
 * In the live preview those last two always run. When deployed they run only if
 * the server confirmed, because nothing else can clear the cookie — a failed or
 * timed-out sign-out throws rather than reporting a sign-out that did not
 * happen.
 * @param {SignOutSteps} steps
 * @returns {Promise<void>}
 */
export async function runSignOut({
  livePreview,
  hasBearer,
  requestSignOut,
  clearToken,
  redirect,
  timeoutMs,
}) {
  if (livePreview) {
    // No bearer means a partitioned iframe with nothing to invalidate; with one,
    // still invalidate it server-side, just don't block on the answer.
    if (hasBearer) {
      await settleWithin(requestSignOut, timeoutMs ?? signOutTimeoutMs(livePreview));
    }
    clearToken();
    redirect();
    return;
  }

  const outcome = await settleWithin(requestSignOut, timeoutMs ?? signOutTimeoutMs(livePreview));
  if (outcome !== "ok") {
    throw new Error(
      outcome === "timeout"
        ? "Sign-out timed out — you are still signed in. Please try again."
        : "Sign-out failed — you are still signed in. Please try again.",
    );
  }
  clearToken();
  redirect();
}

/**
 * @typedef {object} PreSignInSteps
 * @property {boolean} livePreview Whether the app is the sandbox preview iframe.
 * @property {boolean} hasBearer Whether a preview bearer token is stored.
 * @property {() => unknown} requestSignOut Ask the server to end any prior session.
 * @property {() => void} clearToken Drop the stored bearer token.
 * @property {number} [timeoutMs]
 */

/**
 * Drop any prior session before a new sign-in starts, so switching providers
 * actually switches identity.
 *
 * Deliberately BEST EFFORT — unlike `runSignOut` this never throws. It also
 * runs when there is no prior session at all, so treating a failure as fatal
 * would block first-time sign-in on a transport hiccup, for a visitor with no
 * session to protect. The subsequent OAuth flow issues a fresh session either
 * way. Only the wait is bounded, and by the same per-environment rule as
 * `runSignOut`: a deployed session dies server-side, so it gets the full
 * window rather than the preview's aggressive one.
 * @param {PreSignInSteps} steps
 * @returns {Promise<void>}
 */
export async function runPreSignInSignOut({
  livePreview,
  hasBearer,
  requestSignOut,
  clearToken,
  timeoutMs,
}) {
  // In the preview a missing bearer means there is nothing to clear.
  if (hasBearer || !livePreview) {
    await settleWithin(requestSignOut, timeoutMs ?? signOutTimeoutMs(livePreview));
  }
  clearToken();
}

import assert from "node:assert/strict";
import { test } from "node:test";
import {
  DEPLOYED_SIGN_OUT_TIMEOUT_MS,
  PREVIEW_SIGN_OUT_TIMEOUT_MS,
  runPreSignInSignOut,
  runSignOut,
  settleWithin,
  signOutTimeoutMs,
} from "./sign-out-plan.mjs";

const TEST_TIMEOUT_MS = 20;

const hangs = () => new Promise(() => {});
const rejects = () => Promise.reject(new Error("network down"));

/**
 * Drain pending microtasks without advancing mocked time, so "has it finished
 * yet?" is answered by the mocked clock rather than by wall-clock luck.
 * `setImmediate` stays real — only `setTimeout` is mocked.
 */
const flush = () => new Promise((resolve) => setImmediate(resolve));

/**
 * A `runSignOut` call with the browser effects replaced by recorders, so each
 * test asserts on what actually happened rather than on how it was written.
 */
function harness(overrides = {}) {
  /** @type {string[]} */
  const order = [];
  let requests = 0;
  const steps = {
    livePreview: false,
    hasBearer: true,
    requestSignOut: () => {
      requests += 1;
      return Promise.resolve();
    },
    clearToken: () => order.push("clear"),
    redirect: () => order.push("redirect"),
    timeoutMs: TEST_TIMEOUT_MS,
    ...overrides,
  };
  return {
    order,
    get requests() {
      return requests;
    },
    run: () => runSignOut(steps),
  };
}

/** Live preview: the bearer is the session, so the local clear always wins. */
const preview = (overrides = {}) => harness({ livePreview: true, ...overrides });

/** Deployed: only the server can clear the `__Host-` cookie. */
const deployed = (overrides = {}) => harness({ livePreview: false, ...overrides });

// ── Live preview ─────────────────────────────────────────────────────────────

test("preview: a successful sign-out clears the token, then redirects", async () => {
  const h = preview();
  await h.run();
  assert.equal(h.requests, 1);
  assert.deepEqual(h.order, ["clear", "redirect"]);
});

test("preview: a rejected sign-out still clears the token and redirects", async () => {
  const h = preview({ requestSignOut: rejects });
  await h.run();
  assert.deepEqual(h.order, ["clear", "redirect"]);
});

test("preview: a sign-out that throws synchronously still clears and redirects", async () => {
  const h = preview({
    requestSignOut: () => {
      throw new Error("no fetch");
    },
  });
  await h.run();
  assert.deepEqual(h.order, ["clear", "redirect"]);
});

test("preview: a sign-out that never settles clears and redirects once the wait expires", async (t) => {
  t.mock.timers.enable({ apis: ["setTimeout"] });
  const h = preview({ requestSignOut: hangs });
  const done = h.run();

  t.mock.timers.tick(TEST_TIMEOUT_MS - 1);
  await flush();
  assert.deepEqual(h.order, [], "the server still has its window — do not give up early");

  t.mock.timers.tick(1);
  await done;
  assert.deepEqual(h.order, ["clear", "redirect"]);
});

test("preview: no bearer means nothing to invalidate, so no request is made", async () => {
  const h = preview({ hasBearer: false });
  await h.run();
  assert.equal(h.requests, 0);
  assert.deepEqual(h.order, ["clear", "redirect"]);
});

test("preview: a stored bearer is still invalidated server-side", async () => {
  const h = preview({ hasBearer: true });
  await h.run();
  assert.equal(h.requests, 1);
});

// ── Deployed ─────────────────────────────────────────────────────────────────
// JS cannot delete the HttpOnly `__Host-` cookie and `cookieCache` keeps
// serving the cached session, so an unconfirmed sign-out must NOT look like one.

test("deployed: a confirmed sign-out clears the token, then redirects", async () => {
  const h = deployed();
  await h.run();
  assert.deepEqual(h.order, ["clear", "redirect"]);
});

test("deployed: a sign-out that never settles throws and does NOT redirect", async () => {
  const h = deployed({ requestSignOut: hangs });
  await assert.rejects(h.run(), /still signed in/);
  assert.deepEqual(h.order, [], "no redirect may claim a sign-out the server never made");
});

test("deployed: a rejected sign-out throws and does NOT redirect", async () => {
  const h = deployed({ requestSignOut: rejects });
  await assert.rejects(h.run(), /still signed in/);
  assert.deepEqual(h.order, []);
});

test("deployed: the timeout is distinguishable from a rejection", async () => {
  await assert.rejects(deployed({ requestSignOut: hangs }).run(), /timed out/);
  await assert.rejects(deployed({ requestSignOut: rejects }).run(), /Sign-out failed/);
});

// ── Bounded wait (also used by `signIn`'s pre-sign-in session clear) ──────────

test("settleWithin reports the outcome and never rejects", async () => {
  assert.equal(await settleWithin(() => Promise.resolve(), TEST_TIMEOUT_MS), "ok");
  assert.equal(await settleWithin(rejects, TEST_TIMEOUT_MS), "failed");
  assert.equal(await settleWithin(hangs, TEST_TIMEOUT_MS), "timeout");
});

test("settleWithin waits its full window, then gives up rather than hanging", async (t) => {
  t.mock.timers.enable({ apis: ["setTimeout"] });
  let outcome = null;
  const done = settleWithin(hangs, TEST_TIMEOUT_MS).then((o) => (outcome = o));

  t.mock.timers.tick(TEST_TIMEOUT_MS - 1);
  await flush();
  assert.equal(outcome, null, "the request still has time left");

  t.mock.timers.tick(1);
  await done;
  assert.equal(outcome, "timeout", "the caller is never left waiting on a wedged request");
});

// ── Pre-sign-in session clear (`signIn`) ─────────────────────────────────────
// Same per-environment bound as sign-out, but best effort: it also runs when
// there is no prior session, so a failure must never block sign-in.

/** A pre-sign-in clear whose request never settles. */
function preSignIn(livePreview, overrides = {}) {
  let cleared = 0;
  const done = runPreSignInSignOut({
    livePreview,
    hasBearer: true,
    requestSignOut: hangs,
    clearToken: () => (cleared += 1),
    ...overrides,
  });
  return {
    done,
    get cleared() {
      return cleared;
    },
  };
}

test("pre-sign-in: the preview clear gives up at the preview bound", async (t) => {
  t.mock.timers.enable({ apis: ["setTimeout"] });
  const h = preSignIn(true);

  t.mock.timers.tick(PREVIEW_SIGN_OUT_TIMEOUT_MS - 1);
  await flush();
  assert.equal(h.cleared, 0);

  t.mock.timers.tick(1);
  await h.done;
  assert.equal(h.cleared, 1);
});

test("pre-sign-in: a deployed session gets the deployed window, not the preview one", async (t) => {
  t.mock.timers.enable({ apis: ["setTimeout"] });
  const h = preSignIn(false);

  t.mock.timers.tick(PREVIEW_SIGN_OUT_TIMEOUT_MS);
  await flush();
  assert.equal(
    h.cleared,
    0,
    "only the server can end a deployed session — do not start OAuth while it is still live",
  );

  t.mock.timers.tick(DEPLOYED_SIGN_OUT_TIMEOUT_MS - PREVIEW_SIGN_OUT_TIMEOUT_MS);
  await h.done;
  assert.equal(h.cleared, 1);
});

test("pre-sign-in: a failed clear never blocks sign-in", async () => {
  // Best effort by design: this also runs with no prior session to clear.
  await preSignIn(false, { requestSignOut: rejects, timeoutMs: TEST_TIMEOUT_MS }).done;
  await preSignIn(true, { requestSignOut: rejects, timeoutMs: TEST_TIMEOUT_MS }).done;
});

test("pre-sign-in: the preview skips the request when there is no bearer", async () => {
  let requests = 0;
  const h = preSignIn(true, {
    hasBearer: false,
    requestSignOut: () => {
      requests += 1;
      return hangs();
    },
  });
  await h.done;
  assert.equal(requests, 0);
  assert.equal(h.cleared, 1);
});

test("every sign-out bound comes from one rule", () => {
  assert.equal(signOutTimeoutMs(true), PREVIEW_SIGN_OUT_TIMEOUT_MS);
  assert.equal(signOutTimeoutMs(false), DEPLOYED_SIGN_OUT_TIMEOUT_MS);
});

test("the defaults are bounded, and deployed waits longer than preview", async (t) => {
  assert.ok(PREVIEW_SIGN_OUT_TIMEOUT_MS > 0 && PREVIEW_SIGN_OUT_TIMEOUT_MS <= 2000);
  assert.ok(DEPLOYED_SIGN_OUT_TIMEOUT_MS > PREVIEW_SIGN_OUT_TIMEOUT_MS);
  assert.ok(DEPLOYED_SIGN_OUT_TIMEOUT_MS <= 30_000);

  t.mock.timers.enable({ apis: ["setTimeout"] });
  const h = preview({ requestSignOut: hangs, timeoutMs: undefined });
  const done = h.run();
  t.mock.timers.tick(PREVIEW_SIGN_OUT_TIMEOUT_MS);
  await done;
  assert.deepEqual(h.order, ["clear", "redirect"]);
});

#!/usr/bin/env node
/**
 * Run a command with `.grok/app-env.json` merged into its environment.
 *
 * `dev`, `build` and `preview` all route through this wrapper, so the dev
 * server, the built bundle and the preview server can never disagree about
 * `VITE_AUTH_ENABLED` — a divergence that only shows up as a built-output
 * mismatch long after the fact. Anything that starts Vite directly bypasses it.
 *
 * Only `VITE_`-prefixed keys are honored: the file is a build flag carrier, not
 * a secret store, and only `VITE_` vars reach the browser anyway. A real
 * `process.env` entry always wins, so an explicit override still works.
 *
 * That precedence also means the file governs this workspace only. A deployed
 * build runs with the provider's project env, where the deployer sets
 * `VITE_AUTH_ENABLED` itself (today unconditionally `"true"`), so the deployed
 * flag is the platform's, not this file's.
 *
 * Vite picks the values up because `loadEnv` prefix-matches entries already in
 * `process.env`, which is why the merge has to happen before Vite starts.
 */
import { spawn } from "node:child_process";
import { readFileSync, realpathSync } from "node:fs";
import { constants as osConstants } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

export const APP_ENV_REL_PATH = ".grok/app-env.json";

const VITE_PREFIX = "VITE_";

/**
 * Parse an app-env document, keeping only `VITE_`-prefixed string entries.
 * Anything unparseable is an empty environment — a workspace without the file
 * must behave exactly like today (auth on, no overrides).
 */
export function parseAppEnv(text) {
  let parsed;
  try {
    parsed = JSON.parse(text);
  } catch {
    return {};
  }
  if (parsed === null || typeof parsed !== "object" || Array.isArray(parsed)) return {};
  const env = {};
  for (const [key, value] of Object.entries(parsed)) {
    if (!key.startsWith(VITE_PREFIX)) continue;
    if (typeof value !== "string") continue;
    env[key] = value;
  }
  return env;
}

/** The app env recorded under `root`, or `{}` when the file is absent. */
export function readAppEnv(root) {
  try {
    return parseAppEnv(readFileSync(join(root, APP_ENV_REL_PATH), "utf8"));
  } catch {
    return {};
  }
}

/** File values under the process environment: an explicit override wins. */
export function mergeAppEnv(appEnv, processEnv) {
  return { ...appEnv, ...processEnv };
}

/**
 * Translate a child's `exit` `(code, signal)` into this process's exit status.
 *
 * Do not re-raise the signal with `process.kill(process.pid, signal)`: under
 * qemu-user (amd64 image builds on an arm host) a self-directed signal is
 * routinely delivered as SIGSEGV to the wrong process, which takes down the
 * test worker and fails the image build. `128 + signo` is what a shell reports
 * for a signal-killed command, so a cancelled `vite build` is still a failure.
 */
export function exitStatusFromChild(code, signal) {
  if (signal) {
    const signo = osConstants.signals[signal];
    return 128 + (typeof signo === "number" ? signo : 1);
  }
  return code ?? 1;
}

/** The workspace root (this file lives in `<root>/scripts/`). */
export function projectRoot() {
  return dirname(dirname(fileURLToPath(import.meta.url)));
}

/**
 * Whether `moduleUrl` is the script node was asked to run.
 *
 * Both sides are resolved through symlinks: node realpaths `import.meta.url`
 * but leaves `process.argv[1]` as typed, so comparing them raw makes a CLI
 * launched through a symlinked path (`/tmp` on macOS) a silent no-op.
 */
export function isMainModule(moduleUrl) {
  const entry = process.argv[1];
  if (!entry) return false;
  try {
    return realpathSync(entry) === fileURLToPath(moduleUrl);
  } catch {
    return false;
  }
}

function main(argv) {
  const [command, ...args] = argv;
  if (!command) {
    console.error("usage: node scripts/with-app-env.mjs <command> [args…]");
    process.exit(2);
  }
  const env = mergeAppEnv(readAppEnv(projectRoot()), process.env);
  const child = spawn(command, args, { stdio: "inherit", env });
  // The dev server is long-running and is stopped by signalling this wrapper.
  for (const signal of ["SIGINT", "SIGTERM", "SIGHUP"]) {
    process.on(signal, () => child.kill(signal));
  }
  child.on("error", (err) => {
    console.error(`[with-app-env] failed to run ${command}:`, err?.message || err);
    process.exit(127);
  });
  child.on("exit", (code, signal) => {
    process.exit(exitStatusFromChild(code, signal));
  });
}

if (isMainModule(import.meta.url)) {
  main(process.argv.slice(2));
}

import assert from "node:assert/strict";
import { execFile } from "node:child_process";
import { mkdirSync, mkdtempSync, symlinkSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { test } from "node:test";
import { promisify } from "node:util";
import {
  APP_ENV_REL_PATH,
  mergeAppEnv,
  parseAppEnv,
  projectRoot,
  readAppEnv,
} from "./with-app-env.mjs";

const execFileAsync = promisify(execFile);
const WRAPPER = join(projectRoot(), "scripts/with-app-env.mjs");
const PRINT_FLAG = "process.stdout.write(String(process.env.VITE_AUTH_ENABLED));";

function makeWorkspace(appEnvJson) {
  const root = mkdtempSync(join(tmpdir(), "app-env-"));
  if (appEnvJson !== undefined) {
    mkdirSync(join(root, ".grok"), { recursive: true });
    writeFileSync(join(root, APP_ENV_REL_PATH), appEnvJson);
  }
  return root;
}

test("keeps VITE_-prefixed string entries", () => {
  assert.deepEqual(parseAppEnv('{"VITE_AUTH_ENABLED":"false"}'), {
    VITE_AUTH_ENABLED: "false",
  });
});

test("drops non-VITE keys, non-string values and malformed documents", () => {
  assert.deepEqual(parseAppEnv('{"DATABASE_URL":"postgres://x","VITE_N":1,"VITE_OK":"y"}'), {
    VITE_OK: "y",
  });
  assert.deepEqual(parseAppEnv("not json"), {});
  assert.deepEqual(parseAppEnv('["VITE_AUTH_ENABLED"]'), {});
  assert.deepEqual(parseAppEnv("null"), {});
});

test("a missing app-env.json is a clean no-op", () => {
  assert.deepEqual(readAppEnv(makeWorkspace()), {});
});

test("reads the app env from a workspace", () => {
  const root = makeWorkspace('{"VITE_AUTH_ENABLED":"false"}');
  assert.deepEqual(readAppEnv(root), { VITE_AUTH_ENABLED: "false" });
});

test("an explicit process-env override wins over the file", () => {
  const merged = mergeAppEnv(
    { VITE_AUTH_ENABLED: "false" },
    { VITE_AUTH_ENABLED: "true", PATH: "/usr/bin" },
  );
  assert.equal(merged.VITE_AUTH_ENABLED, "true");
  assert.equal(merged.PATH, "/usr/bin");
});

test("the template ships auth off", () => {
  assert.deepEqual(readAppEnv(projectRoot()), { VITE_AUTH_ENABLED: "false" });
});

test("vite loadEnv resolves the wrapped value", () => {
  // What `import.meta.env.VITE_AUTH_ENABLED` becomes: loadEnv prefix-matches
  // process.env, so the wrapper's merge has to land before Vite starts.
  // Do not `import { loadEnv } from "vite"` here — Vite 8 loads rolldown
  // native bindings that SIGSEGV the test worker under qemu-user.
  const root = makeWorkspace('{"VITE_AUTH_ENABLED":"false"}');
  const merged = mergeAppEnv(readAppEnv(root), { PATH: "/usr/bin" });
  assert.equal(merged.VITE_AUTH_ENABLED, "false");
});

test("the wrapped command runs with the app env applied", async () => {
  const { stdout } = await execFileAsync(process.execPath, [
    WRAPPER,
    process.execPath,
    "-e",
    PRINT_FLAG,
  ]);
  assert.equal(stdout, "false");
});

test("the wrapped command sees an explicit override, not the file value", async () => {
  const { stdout } = await execFileAsync(
    process.execPath,
    [WRAPPER, process.execPath, "-e", PRINT_FLAG],
    { env: { ...process.env, VITE_AUTH_ENABLED: "true" } },
  );
  assert.equal(stdout, "true");
});

test("the wrapper propagates the command's exit code", async () => {
  await assert.rejects(
    execFileAsync(process.execPath, [WRAPPER, process.execPath, "-e", "process.exit(3)"]),
    (err) => err.code === 3,
  );
});

test("a signal-killed command is never reported as success", async () => {
  // The wrapper's own SIGTERM handler must not swallow the re-raised signal:
  // a cancelled build reporting exit 0 is a silently passing gate.
  await assert.rejects(
    execFileAsync(process.execPath, [
      WRAPPER,
      process.execPath,
      "-e",
      "process.kill(process.pid, 'SIGTERM');setTimeout(() => {}, 1000);",
    ]),
    (err) => err.signal === "SIGTERM" || err.code !== 0,
  );
});

test("the CLI still runs when invoked through a symlinked path", async () => {
  // node realpaths import.meta.url but not process.argv[1], so a raw comparison
  // turns the wrapper into a no-op that exits 0 without starting anything.
  const link = join(mkdtempSync(join(tmpdir(), "app-env-link-")), "scripts");
  symlinkSync(join(projectRoot(), "scripts"), link);
  const { stdout } = await execFileAsync(process.execPath, [
    join(link, "with-app-env.mjs"),
    process.execPath,
    "-e",
    PRINT_FLAG,
  ]);
  assert.equal(stdout, "false");
});

#!/usr/bin/env node
/**
 * Hand a staged file over to a path another agent reads, in one step.
 *
 *   node scripts/write-atomic.mjs /workspace/.grok/og.jpg.tmp public/og.jpg
 *
 * The brand-asset task writes public/og.jpg and src/lib/og/site.json while the
 * parent may be mid-`npm run build`, so an in-place write can be read
 * half-finished. rename(2) is atomic within one filesystem: a reader sees the
 * old bytes or the new ones. /workspace is one filesystem, so a staged file
 * from anywhere else (/tmp is a separate mount) is refused rather than copied:
 * copying would have to land its temp in the target's directory, which is the
 * one thing a staged path is not allowed to do.
 */
import { existsSync, mkdirSync, renameSync } from "node:fs";
import { dirname, isAbsolute, join, relative, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");

export function parseWriteAtomicArgs(argv) {
  const [staged, target, ...rest] = argv;
  if (!staged || !target) {
    return { error: "usage: node scripts/write-atomic.mjs <staged-file> <target>" };
  }
  if (rest.length > 0) return { error: `unexpected argument: ${rest[0]}` };
  return { staged, target };
}

function isInside(dir, file) {
  const rel = relative(dir, file);
  return rel !== "" && !rel.startsWith("..") && !isAbsolute(rel);
}

/**
 * Why a staged path can be refused: `vite build` copies public/ verbatim into
 * the deployed app, so a temp that lands there ships (and an interrupted run
 * leaves it behind).
 */
export function stagingError({ staged, target, publicDir }) {
  if (staged === target) return `staged file and target are the same path: ${target}`;
  if (isInside(publicDir, staged)) {
    return `stage outside ${publicDir} (vite build ships that directory verbatim): ${staged}`;
  }
  return null;
}

/**
 * Moves `staged` onto `target`, leaving `target` untouched if anything fails.
 * `rename` is injectable because EXDEV — the refusal the "stage under
 * /workspace/.grok/" contract rests on — cannot be provoked portably.
 */
export function handOver(staged, target, { rename = renameSync } = {}) {
  if (!existsSync(staged)) {
    throw Object.assign(new Error(`staged file is missing: ${staged}`), { code: "ENOENT" });
  }
  mkdirSync(dirname(target), { recursive: true });
  try {
    rename(staged, target);
  } catch (err) {
    if (err?.code === "EXDEV") {
      throw new Error(
        `${staged} is on another filesystem than ${target}, so the hand-over cannot be a `
          + "rename — stage under /workspace/.grok/ instead",
      );
    }
    throw err;
  }
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const args = parseWriteAtomicArgs(process.argv.slice(2));
  if (args.error) {
    console.error(`[write-atomic] ${args.error}`);
    process.exit(1);
  }
  // Relative paths follow this script's root, not the caller's cwd: the brand
  // pass runs from wherever its sub-shell left it, and the public/ refusal
  // below is defined against that same root.
  const staged = resolve(ROOT, args.staged);
  const target = resolve(ROOT, args.target);
  const problem = stagingError({ staged, target, publicDir: join(ROOT, "public") });
  if (problem) {
    console.error(`[write-atomic] ${problem}`);
    process.exit(1);
  }
  try {
    handOver(staged, target);
  } catch (err) {
    console.error(`[write-atomic] ${staged} → ${target} failed: ${err?.message || err}`);
    process.exit(1);
  }
  console.log(`[write-atomic] wrote ${target}`);
}

import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import {
  existsSync,
  mkdirSync,
  mkdtempSync,
  readFileSync,
  readdirSync,
  writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { test } from "node:test";
import { handOver, parseWriteAtomicArgs, stagingError } from "./write-atomic.mjs";

const TEMPLATE_ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const SCRIPT = join(TEMPLATE_ROOT, "scripts/write-atomic.mjs");

function makeWorkspace() {
  const root = mkdtempSync(join(tmpdir(), "write-atomic-"));
  mkdirSync(join(root, "public"), { recursive: true });
  mkdirSync(join(root, ".grok"), { recursive: true });
  return root;
}

test("parseWriteAtomicArgs needs exactly a staged file and a target", () => {
  assert.deepEqual(parseWriteAtomicArgs([".grok/og.tmp", "public/og.jpg"]), {
    staged: ".grok/og.tmp",
    target: "public/og.jpg",
  });
  assert.match(parseWriteAtomicArgs([]).error, /usage:/);
  assert.match(parseWriteAtomicArgs([".grok/og.tmp"]).error, /usage:/);
  assert.match(parseWriteAtomicArgs(["a", "b", "c"]).error, /unexpected argument: c/);
});

test("stagingError refuses a temp inside public/ and a no-op move", () => {
  const publicDir = "/workspace/public";
  assert.equal(
    stagingError({
      staged: "/workspace/.grok/og.jpg.tmp",
      target: "/workspace/public/og.jpg",
      publicDir,
    }),
    null,
  );
  assert.match(
    stagingError({
      staged: "/workspace/public/og.jpg.tmp",
      target: "/workspace/public/og.jpg",
      publicDir,
    }),
    /vite build ships that directory verbatim/,
  );
  assert.match(
    stagingError({
      staged: "/workspace/public/og.jpg",
      target: "/workspace/public/og.jpg",
      publicDir,
    }),
    /same path/,
  );
});

test("handOver replaces the target and clears the staged file", () => {
  const root = makeWorkspace();
  const staged = join(root, ".grok/og.jpg.tmp");
  const target = join(root, "public/og.jpg");
  writeFileSync(target, "old card");
  writeFileSync(staged, "new card");

  handOver(staged, target);

  assert.equal(readFileSync(target, "utf8"), "new card");
  assert.equal(existsSync(staged), false);
});

test("handOver creates a missing target directory", () => {
  const root = makeWorkspace();
  const staged = join(root, ".grok/site.json.tmp");
  writeFileSync(staged, '{"title":"Sky Strike"}');

  handOver(staged, join(root, "src/lib/og/site.json"));

  assert.equal(readFileSync(join(root, "src/lib/og/site.json"), "utf8"), '{"title":"Sky Strike"}');
});

test("an interrupted pass leaves the target on its old bytes, temp-free", () => {
  const root = makeWorkspace();
  const target = join(root, "public/og.jpg");
  writeFileSync(target, "old card");
  // The staged file a killed ffmpeg leaves behind: never handed over.
  writeFileSync(join(root, ".grok/og.jpg.tmp"), "half a JPEG");

  assert.equal(readFileSync(target, "utf8"), "old card");
  assert.throws(() => handOver(join(root, ".grok/absent.tmp"), target), { code: "ENOENT" });
  assert.equal(readFileSync(target, "utf8"), "old card");
  assert.equal(existsSync(`${target}.tmp-${process.pid}`), false);
});

test("a failed hand-over creates no directory for the target it never wrote", () => {
  const root = makeWorkspace();
  const missing = join(root, ".grok/absent.tmp");
  assert.throws(() => handOver(missing, join(root, "src/lib/og/site.json")), { code: "ENOENT" });
  assert.equal(existsSync(join(root, "src")), false);
});

test("a staged file on another filesystem is refused, not copied", () => {
  const root = makeWorkspace();
  const staged = join(root, ".grok/og.jpg.tmp");
  const target = join(root, "public/og.jpg");
  writeFileSync(staged, "new card");
  writeFileSync(target, "old card");
  const crossDevice = () => {
    throw Object.assign(new Error("EXDEV"), { code: "EXDEV" });
  };

  assert.throws(() => handOver(staged, target, { rename: crossDevice }), {
    message: /stage under \/workspace\/\.grok\//,
  });
  // Copying would have had to stage its own temp inside public/, which is the
  // one place stagingError refuses.
  assert.deepEqual(readdirSync(join(root, "public")), ["og.jpg"]);
  assert.equal(readFileSync(target, "utf8"), "old card");
});

test("cli: hands the file over, and refuses a temp staged in public/", () => {
  const root = makeWorkspace();
  writeFileSync(join(root, ".grok/og.jpg.tmp"), "new card");
  const ok = spawnSync(
    process.execPath,
    [SCRIPT, join(root, ".grok/og.jpg.tmp"), join(root, "public/og.jpg")],
    { encoding: "utf8" },
  );
  assert.equal(ok.status, 0, ok.stdout + ok.stderr);
  assert.equal(readFileSync(join(root, "public/og.jpg"), "utf8"), "new card");

  // publicDir comes from the script's own root, so refusal is checked there.
  const templateRoot = join(dirname(SCRIPT), "..");
  const staged = join(templateRoot, "public/og.jpg.tmp");
  const refused = spawnSync(
    process.execPath,
    [SCRIPT, staged, join(templateRoot, "public/og.jpg")],
    { encoding: "utf8" },
  );
  assert.equal(refused.status, 1);
  assert.match(refused.stderr, /stage outside/);
  assert.equal(existsSync(staged), false);
});

test("cli: relative paths follow the script's root, not the caller's cwd", () => {
  // Same relative pair the skill documents, run from a workspace that has its
  // own public/: resolving against cwd would take the staged temp out of the
  // directory the refusal is defined against and move it.
  const root = makeWorkspace();
  writeFileSync(join(root, "public/og.jpg.tmp"), "half a JPEG");
  const run = spawnSync(process.execPath, [SCRIPT, "public/og.jpg.tmp", "public/og.jpg"], {
    cwd: root,
    encoding: "utf8",
  });
  assert.equal(run.status, 1, run.stdout + run.stderr);
  assert.match(run.stderr, /stage outside/);
  assert.equal(readFileSync(join(root, "public/og.jpg.tmp"), "utf8"), "half a JPEG");
  assert.equal(existsSync(join(root, "public/og.jpg")), false);
});

test("every hand-over the og skill prints is one this script accepts", () => {
  // The card and banner recipes live in the skill's references/, not SKILL.md.
  const skillDir = join(TEMPLATE_ROOT, ".grok/skills/og");
  const docs = [
    join(skillDir, "SKILL.md"),
    ...readdirSync(join(skillDir, "references")).map((f) => join(skillDir, "references", f)),
  ];
  const invocations = docs.flatMap(
    (path) => readFileSync(path, "utf8").match(/node scripts\/write-atomic\.mjs[^\n`]*/g) ?? [],
  );
  assert.ok(invocations.length >= 3, "og.jpg, x-banner.jpg and site.json each hand over");
  for (const line of invocations) {
    const argv = line.replace("node scripts/write-atomic.mjs", "").trim().split(/\s+/);
    const args = parseWriteAtomicArgs(argv);
    assert.equal(args.error, undefined, line);
    assert.equal(
      stagingError({ staged: args.staged, target: args.target, publicDir: "/workspace/public" }),
      null,
      line,
    );
  }
});

test("cli: a missing staged file fails without touching the target", () => {
  const root = makeWorkspace();
  writeFileSync(join(root, "public/og.jpg"), "old card");
  const run = spawnSync(
    process.execPath,
    [SCRIPT, join(root, ".grok/absent.tmp"), join(root, "public/og.jpg")],
    { encoding: "utf8" },
  );
  assert.equal(run.status, 1);
  assert.match(run.stderr, /\[write-atomic\]/);
  assert.equal(readFileSync(join(root, "public/og.jpg"), "utf8"), "old card");
});

"use client";

import { useEffect, useState } from "react";
import {
  useAccount,
  useConnect,
  useDisconnect,
  useChainId,
  useSwitchChain,
  usePublicClient,
  type Connector,
} from "wagmi";
import { toast } from "sonner";
import { ExternalLink, Smartphone, Wallet, X } from "lucide-react";
import { ClayButton } from "@/components/ui/clay-button";
import { isLiveFactory, ARC_TESTNET_DEPLOYMENT } from "@/lib/wagmi";
import { shortAddr } from "@/lib/utils";
import { arcTestnet } from "@/lib/chains";
import { useLaunchpad } from "@/lib/engine/store.ts";
import { DEMO_USER } from "@/lib/engine/constants.ts";
import { erc20Abi } from "@/lib/abis/launchpad";
import { fromOnChainUsdc } from "@/lib/live-trade";

const DEMO_SESSION_KEY = "pairband.demoWallet.v1";

function hasInjectedProvider(): boolean {
  if (typeof window === "undefined") return false;
  const w = window as Window & { ethereum?: unknown; phantom?: { ethereum?: unknown } };
  return Boolean(w.ethereum || w.phantom?.ethereum);
}

function metaMaskDappLink(): string {
  const href = typeof window !== "undefined" ? window.location.href : "https://pairband.com/app";
  const target = href.replace(/^https?:\/\//, "");
  return `https://metamask.app.link/dapp/${target}`;
}

function connectorLabel(c: Connector): string {
  if (c.id === "metaMaskSDK" || c.type === "metaMask") return "MetaMask";
  if (c.id === "coinbaseWalletSDK" || c.type === "coinbaseWallet") return "Coinbase Wallet";
  if (c.id === "walletConnect" || c.type === "walletConnect") return "WalletConnect";
  if (c.id === "injected") return hasInjectedProvider() ? "Browser wallet" : "Browser wallet";
  return c.name || "Wallet";
}

function readDemoSession(): boolean {
  try {
    return typeof window !== "undefined" && window.localStorage.getItem(DEMO_SESSION_KEY) === "1";
  } catch {
    return false;
  }
}

export function ConnectWallet() {
  const { address, isConnected, status } = useAccount();
  const { connectors, connectAsync, isPending, error } = useConnect();
  const { disconnect } = useDisconnect();
  const chainId = useChainId();
  const { switchChain } = useSwitchChain();
  const publicClient = usePublicClient();
  const live = isLiveFactory(chainId);
  const setAccount = useLaunchpad((s) => s.setAccount);
  const setUsdcBalance = useLaunchpad((s) => s.setUsdcBalance);
  const [sheetOpen, setSheetOpen] = useState(false);
  const [providerReady, setProviderReady] = useState(false);
  const [demoSession, setDemoSession] = useState(false);
  const [busyId, setBusyId] = useState<string | null>(null);

  useEffect(() => {
    setDemoSession(readDemoSession());
    setProviderReady(hasInjectedProvider());
    const onChange = () => setProviderReady(hasInjectedProvider());
    window.addEventListener("ethereum#initialized", onChange);
    const t = window.setInterval(onChange, 1500);
    return () => {
      window.removeEventListener("ethereum#initialized", onChange);
      window.clearInterval(t);
    };
  }, []);

  useEffect(() => {
    if (isConnected && address) {
      setAccount(address);
      if (demoSession) {
        setDemoSession(false);
        try {
          window.localStorage.removeItem(DEMO_SESSION_KEY);
        } catch {
          /* ignore */
        }
      }
    } else if (demoSession) {
      setAccount(DEMO_USER);
    } else {
      setAccount(DEMO_USER);
    }
  }, [isConnected, address, setAccount, demoSession]);

  useEffect(() => {
    if (!isConnected || !address || !publicClient || !ARC_TESTNET_DEPLOYMENT.usdc) return;
    let cancelled = false;
    void (async () => {
      try {
        const raw = (await publicClient.readContract({
          address: ARC_TESTNET_DEPLOYMENT.usdc as `0x${string}`,
          abi: erc20Abi,
          functionName: "balanceOf",
          args: [address],
        })) as bigint;
        if (!cancelled) setUsdcBalance(address, fromOnChainUsdc(raw));
      } catch {
        /* RPC optional during connect */
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [isConnected, address, publicClient, setUsdcBalance, chainId]);

  useEffect(() => {
    if (!error) return;
    const detail =
      error instanceof Error
        ? error.message
        : typeof error === "object" && error && "message" in error
          ? String((error as { message: unknown }).message)
          : "Wallet connection failed";
    toast.error(detail || "Wallet connection failed");
  }, [error]);

  function enableDemo() {
    try {
      window.localStorage.setItem(DEMO_SESSION_KEY, "1");
    } catch {
      /* ignore */
    }
    setDemoSession(true);
    setAccount(DEMO_USER);
    setSheetOpen(false);
    toast.success("Demo wallet ready — trade locally on Discover");
  }

  function clearDemo() {
    try {
      window.localStorage.removeItem(DEMO_SESSION_KEY);
    } catch {
      /* ignore */
    }
    setDemoSession(false);
    setAccount(DEMO_USER);
  }

  async function connectWith(connector: Connector) {
    setBusyId(connector.id);
    try {
      await connectAsync({ connector, chainId: arcTestnet.id });
      setSheetOpen(false);
      toast.success("Wallet connected");
    } catch (e) {
      const msg = e instanceof Error ? e.message : "Connect failed";
      // User rejection is normal — keep the sheet open with a quiet toast.
      if (/reject|denied|cancel/i.test(msg)) {
        toast.message("Connection cancelled");
      } else {
        toast.error(msg);
      }
    } finally {
      setBusyId(null);
    }
  }

  if (isConnected && address) {
    const wrong = chainId !== arcTestnet.id && chainId !== 5042;
    return (
      <div className="flex items-center gap-2">
        {wrong ? (
          <ClayButton
            variant="secondary"
            className="min-h-10 px-3 text-xs"
            onClick={() => switchChain?.({ chainId: arcTestnet.id })}
          >
            Switch to Arc
          </ClayButton>
        ) : (
          <span
            className={`hidden rounded-full px-2.5 py-1 font-mono text-[11px] sm:inline ${
              live ? "bg-teal/15 text-teal" : "bg-ink/8 text-muted"
            }`}
          >
            {live ? "Arc live" : "Wrong network"}
          </span>
        )}
        <ClayButton
          variant="ghost"
          className="min-h-10 px-3 font-mono text-xs"
          onClick={() => {
            disconnect();
            clearDemo();
          }}
        >
          {shortAddr(address, 4)}
        </ClayButton>
      </div>
    );
  }

  if (demoSession) {
    return (
      <ClayButton
        variant="ghost"
        className="min-h-10 px-3 font-mono text-xs"
        onClick={() => {
          clearDemo();
          toast.message("Demo wallet cleared — connect a real wallet anytime");
        }}
        title="Demo wallet (tap to clear)"
      >
        <span className="rounded-full bg-teal/15 px-1.5 py-0.5 text-[10px] font-sans text-teal">Demo</span>
        {shortAddr(DEMO_USER, 4)}
      </ClayButton>
    );
  }

  const uniqueConnectors = connectors.filter((c, i, arr) => arr.findIndex((x) => x.id === c.id) === i);
  // Only treat user-initiated connects as "connecting". Ambient wagmi reconnect
  // (MetaMask/Coinbase SDK) can leave status==="connecting" and look broken.
  const connecting = isPending || busyId !== null;

  return (
    <>
      <ClayButton
        className="min-h-10 px-3 text-xs"
        disabled={connecting && !sheetOpen}
        onClick={() => setSheetOpen(true)}
      >
        {connecting && !sheetOpen ? "Connecting…" : "Connect"}
      </ClayButton>

      {sheetOpen ? (
        <div
          className="fixed inset-0 z-[70] flex items-end justify-center bg-ink/40 p-4 backdrop-blur-sm sm:items-center"
          onClick={(e) => {
            if (e.target === e.currentTarget) setSheetOpen(false);
          }}
        >
          <div
            role="dialog"
            aria-labelledby="connect-sheet-title"
            className="relative w-full max-w-md rounded-3xl border border-ink/10 bg-paper p-6 shadow-[0_24px_64px_rgba(11,15,20,0.28)] dark:border-paper/15 dark:bg-ink-2"
          >
            <button
              type="button"
              onClick={() => setSheetOpen(false)}
              className="absolute top-4 right-4 rounded-full p-2 text-muted hover:bg-ink/5 dark:hover:bg-paper/10"
              aria-label="Close"
            >
              <X size={18} />
            </button>

            <div className="flex size-12 items-center justify-center rounded-2xl bg-teal/15 text-teal">
              <Wallet size={22} />
            </div>
            <h2 id="connect-sheet-title" className="mt-4 font-display text-2xl">
              Connect wallet
            </h2>
            <p className="mt-2 text-sm leading-relaxed text-muted">
              Arc Testnet <span className="font-mono text-ink dark:text-paper">5042002</span>. Pick a wallet, or keep
              trading with the local demo.
            </p>

            <div className="mt-5 flex flex-col gap-2">
              {uniqueConnectors.map((connector) => {
                const isInjectedEmpty = connector.id === "injected" && !providerReady;
                const label = connectorLabel(connector);
                return (
                  <ClayButton
                    key={connector.id}
                    variant="secondary"
                    className="w-full justify-between"
                    disabled={connecting || isInjectedEmpty}
                    onClick={() => void connectWith(connector)}
                  >
                    <span className="inline-flex items-center gap-2">
                      <Wallet size={16} />
                      {busyId === connector.id ? `Opening ${label}…` : label}
                    </span>
                    {isInjectedEmpty ? (
                      <span className="text-xs text-muted">Not detected</span>
                    ) : connector.type === "metaMask" ? (
                      <span className="text-xs text-muted">Extension / app</span>
                    ) : connector.type === "coinbaseWallet" ? (
                      <span className="text-xs text-muted">App / smart wallet</span>
                    ) : connector.type === "walletConnect" ? (
                      <span className="text-xs text-muted">QR / mobile</span>
                    ) : (
                      <span className="text-xs text-muted">Detected</span>
                    )}
                  </ClayButton>
                );
              })}

              <a
                href={metaMaskDappLink()}
                target="_blank"
                rel="noreferrer"
                className="inline-flex min-h-11 w-full items-center justify-between gap-2 rounded-2xl border border-ink/10 bg-transparent px-5 py-2.5 text-sm font-medium text-ink hover:bg-ink/5 dark:border-paper/15 dark:text-paper dark:hover:bg-paper/5"
                onClick={() => setSheetOpen(false)}
              >
                <span className="inline-flex items-center gap-2">
                  <Smartphone size={16} />
                  Open in MetaMask mobile
                </span>
                <ExternalLink size={14} className="text-muted" />
              </a>

              <ClayButton className="w-full" onClick={enableDemo} disabled={connecting}>
                Continue with demo wallet
              </ClayButton>
            </div>

            <p className="mt-4 text-xs leading-relaxed text-muted">
              Preview and some in-app browsers block extensions. On phone, use MetaMask / Coinbase / Phantom’s built-in
              browser, or the MetaMask link above.
            </p>
          </div>
        </div>
      ) : null}
    </>
  );
}

"use client";

import { ladder, spreadBps } from "@/lib/engine/book.ts";
import type { Book } from "@/lib/engine/types.ts";
import { formatPriceWad, formatToken, formatUsdc } from "@/lib/format.ts";
import { cn } from "@/lib/utils";

export function OrderBook({
  book,
  onPrice,
  symbol,
}: {
  book: Book | undefined;
  onPrice?: (price: bigint) => void;
  symbol: string;
}) {
  const { bids, asks } = ladder(book, 8);
  const spread = spreadBps(book);
  const max = [...asks, ...bids].reduce((m, l) => (l.usdc > m ? l.usdc : m), 1n);
  const asksRev = [...asks].reverse();

  return (
    <div className="font-mono text-xs">
      <div className="mb-2 flex items-baseline justify-between">
        <p className="tracking-[0.16em] text-muted uppercase">On-chain book</p>
        <p className="text-muted">
          {spread === null ? "—" : `${(spread / 100).toFixed(2)}% spread`} · {symbol}/USDC
        </p>
      </div>
      <div className="grid grid-cols-3 px-1 text-[10px] tracking-wide text-muted uppercase">
        <span>Price</span>
        <span className="text-right">Size</span>
        <span className="text-right">USDC</span>
      </div>
      <ul className="mt-1 space-y-0.5">
        {asksRev.map((l) => (
          <Level key={`a${l.price}`} level={l} max={max} tone="ask" onPrice={onPrice} />
        ))}
      </ul>
      <p className="my-2 text-center text-[11px] text-muted">
        {asks[0] && bids[0]
          ? `ask ${formatPriceWad(asks[0].price)} · bid ${formatPriceWad(bids[0].price)}`
          : "Empty side — Uniswap backstop"}
      </p>
      <ul className="space-y-0.5">
        {bids.map((l) => (
          <Level key={`b${l.price}`} level={l} max={max} tone="bid" onPrice={onPrice} />
        ))}
      </ul>
    </div>
  );
}

function Level({
  level,
  max,
  tone,
  onPrice,
}: {
  level: { price: bigint; tokens: bigint; usdc: bigint; count: number };
  max: bigint;
  tone: "bid" | "ask";
  onPrice?: (price: bigint) => void;
}) {
  const pct = Number((level.usdc * 1000n) / (max === 0n ? 1n : max)) / 10;
  return (
    <li>
      <button
        type="button"
        onClick={() => onPrice?.(level.price)}
        className="relative flex min-h-8 w-full items-center overflow-hidden rounded-md px-1 text-left"
      >
        <span
          className={cn("absolute inset-y-0 right-0", tone === "bid" ? "bg-teal/20" : "bg-danger/15")}
          style={{ width: `${Math.min(100, pct)}%` }}
        />
        <span className={cn("relative z-[1] flex-1 tabular", tone === "bid" ? "text-teal-2" : "text-danger")}>
          {formatPriceWad(level.price)}
        </span>
        <span className="relative z-[1] flex-1 text-right tabular">{formatToken(level.tokens, 0)}</span>
        <span className="relative z-[1] flex-1 text-right tabular text-muted">{formatUsdc(level.usdc)}</span>
      </button>
    </li>
  );
}

