      </mesh>
      {child === "eth" ? (
        <mesh position={[0, 0.26, 0]} rotation={[0, Math.PI / 4, 0]} castShadow>
          <octahedronGeometry args={[0.18, 0]} />
          <meshStandardMaterial color="#c4b49a" roughness={0.55} />
        </mesh>
      ) : (
        <>
