import { pendingMigrations } from "../../scripts/migration-plan.mjs";

/** Which database backend is active. */
export type DbSource = "neon" | "pglite";

// An empty/whitespace DATABASE_URL (an easy misconfig in deploy UIs) must mean
// "unset" — otherwise production would silently run on the PGLite fallback.
const rawDatabaseUrl =
  typeof process !== "undefined" ? process.env.DATABASE_URL : undefined;
const databaseUrl =
  rawDatabaseUrl && rawDatabaseUrl.trim() ? rawDatabaseUrl : undefined;

/**
 * Active backend: real **Neon** when `DATABASE_URL` is set (deployed / configured
 * sandbox), otherwise a local embedded **PGLite** (Postgres compiled to WASM) so
 * the app has a working database even with nothing configured — the live preview
 * included. Swap in Neon later by just setting `DATABASE_URL`; no code changes.
 */
export const dbSource: DbSource = databaseUrl ? "neon" : "pglite";

/**
 * Minimal shared SQL surface, satisfied by both Neon and PGLite. Both the
 * tagged-template and `.query()` forms resolve to an array of row objects:
 *
 *   const sql = await getSql();
 *   const rows = await sql`select * from todos where id = ${id}`; // parameterized
 *   const rows2 = await sql.query("select * from todos where id = $1", [id]);
 */
export interface Sql {
  <T = Record<string, unknown>>(
    strings: TemplateStringsArray,
    ...values: unknown[]
  ): Promise<T[]>;
  query<T = Record<string, unknown>>(
    text: string,
    params?: unknown[],
  ): Promise<T[]>;
}

/**
 * Init state lives on globalThis as promises: dev HMR creates new instances of
 * this module, and two instances racing module-level state would open a second
 * pool or run two concurrent PGLite migration passes (whose duplicate
 * `_migrations` insert rejects — and would get memoized, poisoning every later
 * `getSql()`). A failed init clears its slot so the next call retries.
 */
const globalRef = globalThis as typeof globalThis & {
  __pgSqlPromise__?: Promise<Sql>;
  __pgliteInstance__?: Promise<import("@electric-sql/pglite").PGlite>;
  __pgliteMigrateChain__?: Promise<void>;
};

/**
 * Result-type parity: Postgres sends every value as text plus a type OID — the
 * JS value is the DRIVER's parsing choice, and pg and PGLite disagree (pg:
 * int8 -> string, date -> local-midnight Date; PGLite: int8 -> BigInt, which
 * JSON.stringify rejects, date -> UTC Date). Normalize both so preview and
 * production return identical, JSON-safe shapes:
 *   int8/bigint (incl. count(*)) -> number (past 2^53 loses precision — cast
 *                                   `::text` if you ever need huge integers)
 *   date                         -> 'YYYY-MM-DD' string
 *   interval                     -> Postgres interval text
 * numeric already comes back as a string on both (arbitrary precision).
 */
const OID_INT8 = 20;
const OID_DATE = 1082;
const OID_INTERVAL = 1186;
const identity = (v: string) => v;

type Run = <T>(text: string, params: unknown[]) => Promise<T[]>;

/** Wrap a query runner in the tagged-template + `.query()` `Sql` surface. */
function toSql(run: Run): Sql {
  const sql = (async <T = Record<string, unknown>>(
    strings: TemplateStringsArray,
    ...values: unknown[]
  ): Promise<T[]> => {
    // Rebuild with $1, $2, … placeholders so values stay parameterized.
    let text = strings[0];
    for (let i = 0; i < values.length; i += 1) text += `$${i + 1}${strings[i + 1]}`;
    return run<T>(text, values);
  }) as unknown as Sql;
  sql.query = <T = Record<string, unknown>>(text: string, params: unknown[] = []) =>
    run<T>(text, params);
  return sql;
}

function createNeonSql(): Promise<Sql> {
  globalRef.__pgSqlPromise__ ??= (async () => {
    // Regular Postgres driver: node-postgres (`pg`) — works directly with Neon's
    // pooled endpoint. One pool per process; warm serverless instances reuse it.
    const { Pool, types } = await import("pg");
    types.setTypeParser(OID_INT8, Number);
    types.setTypeParser(OID_DATE, identity);
    types.setTypeParser(OID_INTERVAL, identity);
    const pool = new Pool({ connectionString: databaseUrl });
    return toSql(async <T>(text: string, params: unknown[]) => {
      const res = await pool.query(text, params);
      return res.rows as T[];
    });
  })().catch((err) => {
    globalRef.__pgSqlPromise__ = undefined;
    throw err;
  });
  return globalRef.__pgSqlPromise__;
}

async function createPgliteSql(): Promise<Sql> {
  // Embedded Postgres, imported on demand so it never loads on the Neon path.
  // One in-memory instance per process, shared across HMR module instances, so
  // data survives source edits (it resets on dev-server restart).
  globalRef.__pgliteInstance__ ??= (async () => {
    const { PGlite } = await import("@electric-sql/pglite");
    const pg = new PGlite({
      parsers: {
        [OID_INT8]: Number,
        [OID_DATE]: identity,
        [OID_INTERVAL]: identity,
      },
    });
    await pg.waitReady;
    await pg.exec(
      "create table if not exists _migrations (name text primary key, applied_at timestamptz not null default now())",
    );
    return pg;
  })().catch((err) => {
    globalRef.__pgliteInstance__ = undefined;
    throw err;
  });
  const pg = await globalRef.__pgliteInstance__;

  // Apply migrations/ (the single schema source) so preview matches production.
  // SQL is inlined by the bundler via import.meta.glob (no runtime fs); applied
  // files are tracked in _migrations. The glob does not descend, so the opt-in
  // auth schema under migrations/auth/ stays out. Runs once per module instance
  // — so an HMR reload after adding a migration file applies it live — with
  // passes serialized on a global chain so concurrent callers never
  // double-apply.
  const migrate = async (): Promise<void> => {
    const migrations = import.meta.glob("/migrations/*.sql", {
      query: "?raw",
      import: "default",
      eager: true,
    }) as Record<string, string>;
    const doneRows = await pg.query<{ name: string }>(
      "select name from _migrations",
    );
    const done = doneRows.rows.map((r) => r.name);
    for (const { name, path } of pendingMigrations(Object.keys(migrations), done)) {
      // Apply + record atomically (parity with scripts/migrate.mjs) so a failed
      // statement can't leave a file half-applied but untracked.
      await pg.transaction(async (tx) => {
        await tx.exec(migrations[path]);
        await tx.query("insert into _migrations (name) values ($1)", [name]);
      });
    }
  };
  const pass = (globalRef.__pgliteMigrateChain__ ?? Promise.resolve())
    .catch(() => undefined) // an earlier failed pass must not wedge the chain
    .then(migrate);
  globalRef.__pgliteMigrateChain__ = pass;
  await pass;

  return toSql(async <T>(text: string, params: unknown[]) => {
    const result = await pg.query<T>(text, params);
    return result.rows;
  });
}

let sqlPromise: Promise<Sql> | null = null;

async function createSql(): Promise<Sql> {
  if (typeof window !== "undefined") {
    throw new Error(
      "@/lib/db is server-only — call getSql() from a createServerFn handler " +
        "or a server route loader, never from client code.",
    );
  }
  return dbSource === "neon" ? createNeonSql() : createPgliteSql();
}

/**
 * Get the shared, **server-only** SQL client. Neon when `DATABASE_URL` is set,
 * otherwise the local PGLite fallback. Memoized — safe to call per request.
 *
 * Schema comes from `migrations/*.sql`, auto-applied before the first query on
 * both backends — define tables there, never inline in server functions.
 */
export function getSql(): Promise<Sql> {
  sqlPromise ??= createSql().catch((err) => {
    sqlPromise = null; // don't memoize failures — let the next call retry
    throw err;
  });
  return sqlPromise;
}

/**
 * The shared PGLite instance (preview only), with `migrations/*.sql` applied.
 * Lets Better Auth persist to the SAME embedded DB as app data in preview (via a
 * Kysely dialect). Throws when `DATABASE_URL` is set (that path uses Neon).
 */
export async function getPglite(): Promise<import("@electric-sql/pglite").PGlite> {
  if (dbSource !== "pglite") {
    throw new Error("getPglite() is only available on the PGLite fallback (no DATABASE_URL)");
  }
  await getSql();
  const pg = await globalRef.__pgliteInstance__;
  if (!pg) throw new Error("PGLite instance failed to initialize");
  return pg;
}

/**
 * Finish DB bootstrap before the server handles traffic.
 *
 * - **PGLite** (preview / no `DATABASE_URL`): open the in-memory DB and apply
 *   `migrations/*.sql`. Idempotent — concurrent callers share one promise.
 * - **Neon**: no-op (pool is created lazily on first query).
 *
 * Vite `configureServer` awaits this at dev startup; production imports of this
 * module kick it off immediately (see bottom of file).
 */
export function ensureDbReady(): Promise<void> {
  if (dbSource !== "pglite") return Promise.resolve();
  return getSql().then(() => undefined);
}

// Server-only eager start: kick PGLite bootstrap as soon as this module loads in
// Node. Client bundles never hit this path (`getSql` throws in the browser).
const globalBoot = globalThis as typeof globalThis & {
  __pgBootstrapPromise__?: Promise<void>;
};
if (typeof window === "undefined" && dbSource === "pglite") {
  globalBoot.__pgBootstrapPromise__ ??= ensureDbReady().catch((err) => {
    globalBoot.__pgBootstrapPromise__ = undefined;
    console.error("[db] PGLite bootstrap failed:", err);
    throw err;
  });
}

import { AMM_FEE_BPS, BPS_DENOM } from "./constants.ts";
import { LaunchError } from "./types.ts";

export function getAmountOut(amountIn: bigint, reserveIn: bigint, reserveOut: bigint): bigint {
  if (amountIn <= 0n) throw new LaunchError("ZeroAmount");
  if (reserveIn === 0n || reserveOut === 0n) throw new LaunchError("InsufficientLiquidity");
  const amountInWithFee = amountIn * (BPS_DENOM - AMM_FEE_BPS);
  const numerator = amountInWithFee * reserveOut;
  const denominator = reserveIn * BPS_DENOM + amountInWithFee;
  const out = numerator / denominator;
  if (out <= 0n || out >= reserveOut) throw new LaunchError("InsufficientLiquidity");
  return out;
}

export function quote(amountIn: bigint, reserveIn: bigint, reserveOut: bigint): bigint {
  if (amountIn <= 0n || reserveIn === 0n) return 0n;
  return (amountIn * reserveOut) / reserveIn;
}

/** Mid vs execution, in basis points. Includes the 0.3% Uniswap fee. */
export function priceImpactBps(amountIn: bigint, reserveIn: bigint, reserveOut: bigint): number {
  if (amountIn <= 0n || reserveIn === 0n || reserveOut === 0n) return 0;
  const mid = quote(amountIn, reserveIn, reserveOut);
  if (mid === 0n) return 0;
  try {
    const exec = getAmountOut(amountIn, reserveIn, reserveOut);
    if (exec >= mid) return 0;
    return Number(((mid - exec) * 10_000n) / mid);
  } catch {
    return 10_000;
  }
}

export function poolK(reserve0: bigint, reserve1: bigint): bigint {
  return reserve0 * reserve1;
}

/** Uniswap v3-style sqrtPriceX96 = sqrt(token1/token0) * 2^96. token1 = USDC, token0 = token. */
export function sqrtPriceX96(reserveToken: bigint, reserveUsdc: bigint): bigint {
  if (reserveToken <= 0n || reserveUsdc <= 0n) return 0n;
  const Q96 = 2n ** 96n;
  return (sqrt(reserveUsdc) * Q96) / sqrt(reserveToken);
}

export function sqrt(v: bigint): bigint {
  if (v <= 0n) return 0n;
  let z = v;
  let x = v / 2n + 1n;
  while (x < z) {
    z = x;
    x = (v / x + x) / 2n;
  }
  return z;
}

/** Tick alignment, width, L1 shift, in-range. Mirrors BandMath.sol. */

export class BandError extends Error {
  readonly code: string;
  constructor(code: string, message: string) {
    super(message);
    this.code = code;
    this.name = "BandError";
  }
}

export function align(tick: number, spacing: number): number {
  if (spacing <= 0) throw new BandError("InvalidTicks", "spacing must be > 0");
  let compressed = Math.trunc(tick / spacing);
  if (tick < 0 && tick % spacing !== 0) compressed -= 1;
  return compressed * spacing;
}

export function width(tickLower: number, tickUpper: number): number {
  if (tickLower >= tickUpper) throw new BandError("InvalidTicks", "inverted band");
  return tickUpper - tickLower;
}

/** L1 shift: |Δlower| + |Δupper|. Documented in BandMath.sol NatSpec. */
export function shift(
  curLower: number,
  curUpper: number,
  newLower: number,
  newUpper: number,
): number {
  return Math.abs(newLower - curLower) + Math.abs(newUpper - curUpper);
}

export function inRange(tick: number, tickLower: number, tickUpper: number): boolean {
  return tick >= tickLower && tick < tickUpper;
}

export function validateBand(
  tickLower: number,
  tickUpper: number,
  spacing: number,
  maxWidth: number,
): void {
  if (spacing <= 0) throw new BandError("InvalidTicks", "spacing");
  if (tickLower >= tickUpper) throw new BandError("InvalidTicks", "inverted");
  if (tickLower % spacing !== 0 || tickUpper % spacing !== 0) {
    throw new BandError("InvalidTicks", "unaligned");
  }
  const w = tickUpper - tickLower;
  if (w > maxWidth) throw new BandError("TooWide", `width ${w} > maxWidth ${maxWidth}`);
  if (w % spacing !== 0) throw new BandError("InvalidTicks", "width not multiple of spacing");
}

import assert from "node:assert/strict";
import { describe, it } from "node:test";
import { WAD } from "./constants.ts";
import { emptyBook, insertOrder, matchAsks, matchBids, cancelOrder } from "./book.ts";
import { LaunchError, type RestingOrder } from "./types.ts";

function ask(id: number, price: bigint, tok: bigint): RestingOrder {
  return {
    id,
    launchId: "x",
    owner: "0xMAKER",
    side: "ask",
    price,
    remaining: tok,
    escrow: tok,
    createdAt: 1,
  };
}

function bid(id: number, price: bigint, tok: bigint): RestingOrder {
  return {
    id,
    launchId: "x",
    owner: "0xMAKER",
    side: "bid",
    price,
    remaining: tok,
    escrow: (tok * price) / WAD,
    createdAt: 1,
  };
}

describe("on-chain book twin", () => {
  it("fills asks price-time (lowest first)", () => {
    const book = emptyBook();
    insertOrder(book, ask(1, 2n * WAD, 10n * WAD));
    insertOrder(book, ask(2, 1n * WAD, 10n * WAD));
    const m = matchAsks(book, 5n * WAD);
    assert.equal(m.fills.length, 1);
    assert.equal(m.fills[0]!.orderId, 2);
    assert.equal(m.tokensOut, 5n * WAD);
    assert.equal(book.asks[0]!.id, 2);
    assert.equal(book.asks[0]!.remaining, 5n * WAD);
  });

  it("walks multiple levels", () => {
    const book = emptyBook();
    insertOrder(book, ask(1, WAD, 3n * WAD));
    insertOrder(book, ask(2, 2n * WAD, 10n * WAD));
    const m = matchAsks(book, 5n * WAD);
    assert.equal(m.fills.length, 2);
    assert.equal(m.tokensOut, 4n * WAD); // 3 at 1 + 1 at 2
    assert.equal(m.leftoverUsdc, 0n);
  });

  it("limit price stops the walk", () => {
    const book = emptyBook();
    insertOrder(book, ask(1, WAD, 10n * WAD));
    insertOrder(book, ask(2, 3n * WAD, 10n * WAD));
    const m = matchAsks(book, 100n * WAD, WAD);
    assert.equal(m.fills.length, 1);
    assert.ok(m.leftoverUsdc > 0n);
  });

  it("bids fill highest first", () => {
    const book = emptyBook();
    insertOrder(book, bid(1, WAD, 5n * WAD));
    insertOrder(book, bid(2, 2n * WAD, 5n * WAD));
    const m = matchBids(book, 3n * WAD);
    assert.equal(m.fills[0]!.orderId, 2);
    assert.equal(m.usdcOut, 6n * WAD);
  });

  it("cancel returns only the owner", () => {
    const book = emptyBook();
    insertOrder(book, ask(1, WAD, 1n * WAD));
    assert.throws(() => cancelOrder(book, 1, "0xOTHER"), (e: LaunchError) => e.code === "NotOwner");
    const o = cancelOrder(book, 1, "0xMAKER");
    assert.equal(o.remaining, 1n * WAD);
    assert.equal(book.asks.length, 0);
  });
});

import { WAD } from "./constants.ts";
import { getAmountOut } from "./amm.ts";
import { LaunchError, type Book, type Fill, type Launch, type RestingOrder } from "./types.ts";

export function emptyBook(): Book {
  return { bids: [], asks: [], nextId: 1 };
}

export function tokensToUsdc(tokens: bigint, price: bigint): bigint {
  return (tokens * price) / WAD;
}

export function usdcToTokens(usdc: bigint, price: bigint): bigint {
  if (price === 0n) return 0n;
  return (usdc * WAD) / price;
}

function sortBook(book: Book) {
  book.bids.sort((a, b) => (a.price === b.price ? a.id - b.id : a.price < b.price ? 1 : -1));
  book.asks.sort((a, b) => (a.price === b.price ? a.id - b.id : a.price > b.price ? 1 : -1));
}

export function insertOrder(book: Book, order: RestingOrder) {
  if (order.side === "bid") book.bids.push(order);
  else book.asks.push(order);
  sortBook(book);
}

export function matchAsks(
  book: Book,
  usdcIn: bigint,
  limitPrice?: bigint,
): { fills: Fill[]; leftoverUsdc: bigint; tokensOut: bigint } {
  const fills: Fill[] = [];
  let usdcLeft = usdcIn;
  let tokensOut = 0n;
  while (usdcLeft > 0n && book.asks.length > 0) {
    const o = book.asks[0]!;
    if (limitPrice !== undefined && o.price > limitPrice) break;
    const maxTok = usdcToTokens(usdcLeft, o.price);
    const fillTok = maxTok < o.remaining ? maxTok : o.remaining;
    const fillUsdc = tokensToUsdc(fillTok, o.price);
    if (fillTok === 0n || fillUsdc === 0n) break;
    fills.push({
      orderId: o.id,
      owner: o.owner,
      side: "ask",
      price: o.price,
      tokens: fillTok,
      usdc: fillUsdc,
    });
    o.remaining -= fillTok;
    o.escrow -= fillTok;
    usdcLeft -= fillUsdc;
    tokensOut += fillTok;
    if (o.remaining === 0n) book.asks.shift();
  }
  return { fills, leftoverUsdc: usdcLeft, tokensOut };
}

export function matchBids(
  book: Book,
  tokensIn: bigint,
  limitPrice?: bigint,
): { fills: Fill[]; leftoverTokens: bigint; usdcOut: bigint } {
  const fills: Fill[] = [];
  let tokensLeft = tokensIn;
  let usdcOut = 0n;
  while (tokensLeft > 0n && book.bids.length > 0) {
    const o = book.bids[0]!;
    if (limitPrice !== undefined && o.price < limitPrice) break;
    const fillTok = tokensLeft < o.remaining ? tokensLeft : o.remaining;
    const fillUsdc = tokensToUsdc(fillTok, o.price);
    if (fillTok === 0n || fillUsdc === 0n) break;
    fills.push({
      orderId: o.id,
      owner: o.owner,
      side: "bid",
      price: o.price,
      tokens: fillTok,
      usdc: fillUsdc,
    });
    o.remaining -= fillTok;
    o.escrow -= fillUsdc;
    tokensLeft -= fillTok;
    usdcOut += fillUsdc;
    if (o.remaining === 0n) book.bids.shift();
  }
  return { fills, leftoverTokens: tokensLeft, usdcOut };
}

export function previewMarketBuy(
  book: Book,
  launch: Launch,
  usdcIn: bigint,
): { tokensOut: bigint; bookUsdc: bigint; ammUsdc: bigint; impactBps: number } {
  const asks = book.asks.map((o) => ({ ...o }));
  const ghost: Book = { bids: [], asks, nextId: book.nextId };
  const m = matchAsks(ghost, usdcIn);
  let ammOut = 0n;
  if (m.leftoverUsdc > 0n && launch.reserveUsdc > 0n && launch.reserveToken > 0n) {
    try {
      ammOut = getAmountOut(m.leftoverUsdc, launch.reserveUsdc, launch.reserveToken);
    } catch {
      ammOut = 0n;
    }
  }
  const tokensOut = m.tokensOut + ammOut;
  const bookUsdc = usdcIn - m.leftoverUsdc;
  const ammUsdc = ammOut > 0n ? m.leftoverUsdc : 0n;
  const spent = bookUsdc + ammUsdc;
  const mid = bookMid(book) ?? (launch.reserveToken === 0n ? 0n : (launch.reserveUsdc * WAD) / launch.reserveToken);
  const fair = mid === 0n ? tokensOut : usdcToTokens(spent || usdcIn, mid);
  const impact =
    fair > tokensOut && fair > 0n ? Number(((fair - tokensOut) * 10_000n) / fair) : 0;
  return { tokensOut, bookUsdc, ammUsdc, impactBps: impact };
}

export function previewMarketSell(
  book: Book,
  launch: Launch,
  tokensIn: bigint,
): { usdcOut: bigint; bookTokens: bigint; ammTokens: bigint; impactBps: number } {
  const bids = book.bids.map((o) => ({ ...o }));
  const ghost: Book = { bids, asks: [], nextId: book.nextId };
  const m = matchBids(ghost, tokensIn);
  let ammOut = 0n;
  if (m.leftoverTokens > 0n && launch.reserveUsdc > 0n && launch.reserveToken > 0n) {
    try {
      ammOut = getAmountOut(m.leftoverTokens, launch.reserveToken, launch.reserveUsdc);
    } catch {
      ammOut = 0n;
    }
  }
  const usdcOut = m.usdcOut + ammOut;
  const mid = bookMid(book) ?? (launch.reserveToken === 0n ? 0n : (launch.reserveUsdc * WAD) / launch.reserveToken);
  const fair = mid === 0n ? usdcOut : tokensToUsdc(tokensIn, mid);
  const impact = fair > usdcOut && fair > 0n ? Number(((fair - usdcOut) * 10_000n) / fair) : 0;
  return {
    usdcOut,
    bookTokens: tokensIn - m.leftoverTokens,
    ammTokens: ammOut > 0n ? m.leftoverTokens : 0n,
    impactBps: impact,
  };
}

export function bookMid(book: Book | undefined): bigint | null {
  if (!book?.bids.length || !book.asks.length) return null;
  return (book.bids[0]!.price + book.asks[0]!.price) / 2n;
}

export function spreadBps(book: Book | undefined): number | null {
  if (!book?.bids.length || !book.asks.length) return null;
  const bid = book.bids[0]!.price;
  const ask = book.asks[0]!.price;
  if (bid === 0n) return null;
  return Number(((ask - bid) * 10_000n) / bid);
}

export type LadderLevel = { price: bigint; tokens: bigint; usdc: bigint; count: number };

export function ladder(book: Book | undefined, depth = 8): { bids: LadderLevel[]; asks: LadderLevel[] } {
  if (!book) return { bids: [], asks: [] };
  const group = (orders: RestingOrder[], n: number) => {
    const map = new Map<string, LadderLevel>();
    for (const o of orders) {
      const k = o.price.toString();
      const cur = map.get(k) ?? { price: o.price, tokens: 0n, usdc: 0n, count: 0 };
      cur.tokens += o.remaining;
      cur.usdc += tokensToUsdc(o.remaining, o.price);
      cur.count += 1;
      map.set(k, cur);
      if (map.size >= n) break;
    }
    return [...map.values()];
  };
  return { bids: group(book.bids, depth), asks: group(book.asks, depth) };
}

export function cancelOrder(book: Book, id: number, owner: string): RestingOrder {
  const fromBids = book.bids.findIndex((o) => o.id === id);
  const fromAsks = book.asks.findIndex((o) => o.id === id);
  const o = fromBids >= 0 ? book.bids[fromBids] : fromAsks >= 0 ? book.asks[fromAsks] : undefined;
  if (!o) throw new LaunchError("OrderNotFound");
  if (o.owner.toLowerCase() !== owner.toLowerCase()) throw new LaunchError("NotOwner");
  if (fromBids >= 0) book.bids.splice(fromBids, 1);
  else book.asks.splice(fromAsks, 1);
  return o;
}

export function seedBook(
  launch: Launch,
  makers: readonly string[],
  debitToken: (account: string, amount: bigint) => boolean,
  takeUsdc: (account: string, amount: bigint) => void,
  now: number,
): Book {
  const book = emptyBook();
  const mid =
    launch.reserveToken === 0n ? 0n : (launch.reserveUsdc * WAD) / launch.reserveToken;
  if (mid === 0n) return book;
  const bps = [15n, 40n, 80n, 130n, 200n, 300n];
  for (let i = 0; i < bps.length; i++) {
    const maker = makers[i % makers.length]!;
    const askP = mid + (mid * bps[i]!) / 10_000n;
    const bidP = mid - (mid * bps[i]!) / 10_000n;
    const usdcSize = (1n + BigInt(i)) * WAD;
    const askTok = usdcToTokens(usdcSize, askP);
    const bidTok = usdcToTokens(usdcSize, bidP);
    if (askTok > 0n && debitToken(maker, askTok)) {
      insertOrder(book, {
        id: book.nextId++,
        launchId: launch.id,
        owner: maker,
        side: "ask",
        price: askP,
        remaining: askTok,
        escrow: askTok,
        createdAt: now,
      });
    }
    if (bidTok > 0n && bidP > 0n) {
      const escrow = tokensToUsdc(bidTok, bidP);
      takeUsdc(maker, escrow);
      insertOrder(book, {
        id: book.nextId++,
        launchId: launch.id,
        owner: maker,
        side: "bid",
        price: bidP,
        remaining: bidTok,
        escrow,
        createdAt: now,
      });
    }
  }
  return book;
}

import assert from "node:assert/strict";
import { describe, it } from "node:test";
import { ARC_CCTP_DOMAIN } from "./cctp.ts";
import { DEMO_USER, WAD } from "./constants.ts";
import { buy, createEngine, sourceBalance, usdcBalance, bridgeOut } from "./launchpad.ts";

describe("CCTP settle on Arc", () => {
  it("buy from Base burns remote USDC and settles on Arc", () => {
    const s = createEngine();
    const paper = s.launches.find((l) => l.symbol === "PAPER")!;
    const user = DEMO_USER;
    const baseBefore = sourceBalance(s, user, 6);
    const arcBefore = usdcBalance(s, user);
    assert.ok(baseBefore >= 10n * WAD);
    const next = buy(s, user, paper.id, 10n * WAD, 0n, 6);
    assert.equal(sourceBalance(next, user, 6), baseBefore - 10n * WAD);
    assert.equal(usdcBalance(next, user), arcBefore);
    const t = next.trades[0]!;
    assert.equal(t.sourceDomain, 6);
    assert.equal(t.destDomain, ARC_CCTP_DOMAIN);
    assert.ok(t.tokens > 0n);
  });

  it("unknown domain reverts", () => {
    const s = createEngine();
    const paper = s.launches.find((l) => l.symbol === "PAPER")!;
    const user = DEMO_USER;
    assert.throws(() => buy(s, user, paper.id, WAD, 0n, 99), (e: { code: string }) => e.code === "UnknownDomain");
  });

  it("bridgeOut credits destination, debit Arc", () => {
    const s = createEngine();
    const user = DEMO_USER;
    const arcBefore = usdcBalance(s, user);
    const ethBefore = sourceBalance(s, user, 0);
    const next = bridgeOut(s, user, 0, 100n * WAD);
    assert.equal(usdcBalance(next, user), arcBefore - 100n * WAD);
    assert.equal(sourceBalance(next, user, 0), ethBefore + 100n * WAD);
    assert.equal(next.trades[0]!.side, "bridge");
  });

  it("Arc-native buy does not touch remotes", () => {
    const s = createEngine();
    const paper = s.launches.find((l) => l.symbol === "PAPER")!;
    const user = DEMO_USER;
    const baseBefore = sourceBalance(s, user, 6);
    const next = buy(s, user, paper.id, 5n * WAD, 0n, 26);
    assert.equal(sourceBalance(next, user, 6), baseBefore);
  });
});

