import { amountsAtBand, liquidityAtBand, nextSqrtFromInput } from "./liquidity.ts";
import { AGENT_FEE_VAULT_USDC } from "./constants.ts";
import {
  DEAD,
  DEMO_AGENT,
  DEMO_CURATOR,
  DEMO_FACTORY,
  DEMO_HOOK,
  DEMO_POOL_ID,
  DEMO_PROTOCOL,
  DEMO_USDC,
  DEMO_USD1,
  DEMO_USER,
  DEMO_VAULT,
  MIN_BOOTSTRAP,
  MIN_DEAD_SHARES,
