    return rows;
  }, [engine, q, version]);

  if (!launch) {
    return <p className="px-4 py-16 text-center text-muted">No markets yet.</p>;
  }

  const series = priceSeries(engine, launch.id);
  const trades = engine.trades.filter((t) => t.launchId === launch.id);

